// Bản đồ học tập biên soạn từ các chủ đề và tài liệu đã đối chiếu trong từng khóa.
// Luồng là khung tư duy/triển khai; thực tế có thể quay lại bước trước theo bằng chứng.
(() => {
  const all={};
  const O=(day,why,outcome,flow,must,should,later,example,traps,checks)=>{
    all[day]={why,outcome,flow:flow.map(([title,body,output])=>({title,body,output})),must:must.map(([topic,title,body])=>({topic,title,body})),should,later,example:{situation:example[0],steps:example[1],verify:example[2]},traps,checks:checks.map(([question,answer])=>({question,answer}))};
  };

  O(16,
    'Một agent mạnh cần cơ chế phát hiện lỗi, chọn cách thử lại và kiểm soát hành động. Thêm vòng suy luận chỉ hữu ích khi đo được lợi ích so với chi phí.',
    'Đọc một lần chạy thất bại và chọn đúng lớp cần sửa: evaluator, memory, search, context hay quyền tool.',
    [['Chạy baseline','Dùng một agent với cùng task và ngân sách để biết lỗi nằm ở đâu.','Trace và kết quả gốc'],['Đánh giá','Evaluator (bộ đánh giá) kiểm kết quả và từng hành động bằng tiêu chí quan sát được.','Lỗi có bằng chứng'],['Chọn cơ chế','Dùng Reflexion khi cần học từ lần thử; search khi cần so nhánh; skill khi cần tái dùng thao tác.','Một giả thuyết sửa lỗi'],['Thực thi có giới hạn','Harness (lớp điều khiển quanh model) cưỡng chế quyền, thời gian, số bước và quản lý context.','Hành động nằm trong quyền'],['Verify rồi giữ bài học','Kiểm artifact và nguồn; chỉ lưu kỹ năng hoặc bài học đã qua kiểm định. Quay lại đánh giá nếu chưa đạt.','Kết quả cùng bằng chứng']],
    [['Giới hạn ReAct','ReAct và lỗi lan truyền','ReAct (vòng suy luận–hành động–quan sát) có thể lặp hoặc đi sai từ observation nhiễu; cần đọc trace trước khi thêm kiến trúc.'],['Vòng Reflexion','Phản tỉnh phải đổi được lần thử sau','Reflexion (rút bài học từ phản hồi) thay context hoặc memory giữa các lần thử, không mặc định cập nhật trọng số. Evaluator sai có thể khiến phản tỉnh sai.'],['LATS và tìm kiếm','Search phải có tiêu chí và budget','LATS (tìm kiếm nhánh hành động cho agent) dùng nhiều ứng viên để tìm phương án; chất lượng tăng phải được cân với token và độ trễ.'],['Plan–Act–Verify','Kế hoạch và bằng chứng hoàn tất','Plan–Act–Verify (lập kế hoạch–thực thi–kiểm chứng) tách việc định làm khỏi việc thật sự đã xong; một lời báo thành công chưa đủ.'],['Capability control và defence in depth','Quyền được cưỡng chế bằng code','Capability control (kiểm soát năng lực và quyền) chặn thao tác ngoài phạm vi trước execution; lời nhắc trong prompt không thay authorization.']],
    ['Hiểu vai trò sáu hook middleware để đặt kiểm tra trước/sau đúng sự kiện.','Phân biệt compaction (nén context) với eviction (loại context ít giá trị); giữ mục tiêu và constraints.'],
    ['Đọc sâu thuật toán tree search và process reward khi task của bạn cần so sánh nhiều đường giải.'],
    ['Agent review PR đọc sai file rồi lặp lại cùng nhận xét qua ba lần thử.',['Tìm bước chọn file sai trong trace.','Cho evaluator đối chiếu nhận xét với diff; ghi bài học cụ thể về chọn file.','Giữ budget cố định khi so lại baseline và bản sửa.'],'Nhận xét phải trỏ đúng dòng và được diff hỗ trợ; báo thêm chi phí và thời gian.'],
    ['Thêm agent hoặc tăng số lần thử không tự chứng minh hệ thống tốt hơn.','Không để agent sửa grader hoặc tắt gate để nâng điểm.'],
    [['Reflexion khác fine-tuning ở đâu?','Reflexion thường dùng phản hồi trong context/memory khi suy luận; fine-tuning thay trọng số qua huấn luyện.'],['Vì sao đáp án đúng vẫn có thể bị đánh fail?','Agent có thể đạt kết quả bằng hành động trái quyền, nguồn không hợp lệ hoặc vi phạm ràng buộc.'],['Khi nào nên thêm search?','Khi task có các nhánh đáng so sánh, evaluator phân biệt được chất lượng và lợi ích vượt chi phí trong budget.']]);

  O(17,
    'Memory là dữ liệu hệ thống chủ động lưu và truy xuất theo identity, thời gian và mục đích. Context dài không tự tạo trí nhớ đúng qua nhiều phiên.',
    'Thiết kế agent nhớ đúng người, dùng fact mới và có thể giải thích, cập nhật hoặc xóa điều đã nhớ.',
    [['Xác định phạm vi','Phân biệt user, thread và dữ liệu được phép nhớ.','Identity và policy lưu'],['Chọn loại memory','Chọn dữ kiện, kinh nghiệm hay quy trình theo nhu cầu thay vì lưu toàn transcript.','Thông tin có loại và nguồn'],['Ghi và cập nhật','Gắn thời gian, version và xử lý conflict; chọn ghi ngay hoặc job nền theo độ tươi cần thiết.','Memory có vòng đời'],['Retrieve và chọn context','Chỉ lấy phần liên quan, còn hiệu lực và đúng user vào ngân sách context.','Context đủ dùng'],['Đo và bảo trì','Test qua phiên mới, thay đổi fact, yêu cầu xóa và memory poisoning.','Bộ nhớ đáng tin hơn baseline']],
    [['Bốn loại memory','Phân loại theo chức năng','Bài giảng dùng bốn nhóm thực hành: short-term/working (bộ nhớ tạm của phiên), long-term (facts/sở thích qua phiên), episodic (trải nghiệm có diễn biến) và semantic (tri thức được truy xuất). Procedural memory (bộ nhớ cách làm/skills) là phần bổ sung. Các nhóm có thể chồng lấn trong cách phân loại khác.'],['Checkpoint và Store','State của thread và dữ liệu qua phiên','Checkpoint (ảnh chụp trạng thái để tiếp tục) giữ tiến trình của thread; Store (kho dữ liệu có namespace) có thể phục vụ nhớ qua nhiều thread theo quyền.'],['Token budget và trim','Bộ nhớ phải được chọn','Lưu nhiều không có nghĩa đưa hết vào model. Chọn theo relevance, độ mới và constraint; giữ đường truy về nguồn khi nén.'],['Consent và xóa memory','Người dùng kiểm soát điều được nhớ','Consent (đồng ý cho phép lưu) cần gắn mục đích; xóa phải xét bản gốc, index, cache và các bản sao theo policy.'],['Memory hot path và background write','Đường ghi quyết định độ tươi','Ghi trong request giúp lượt sau thấy sớm nhưng tăng latency; ghi nền cần xử lý khoảng trễ, retry và conflict.']],
    ['Biết TTL (thời hạn tồn tại), cơ chế cập nhật và phân biệt hết hạn với xóa chủ động.','Theo dõi memory hit rate cùng mức hữu ích; lấy đúng một bản ghi không chứng minh trả lời đúng.'],
    ['So sánh managed memory và tự xây bằng benchmark phù hợp thay vì chỉ nhìn tên framework.'],
    ['User đổi địa chỉ giao hàng nhưng phiên mới vẫn nhắc địa chỉ cũ.',['Kiểm namespace, version và dấu thời gian của hai địa chỉ.','Đánh dấu fact cũ hết hiệu lực, cập nhật store/index/cache liên quan.','Kiểm cả phiên đang chạy, phiên mới và tài khoản khác.'],'Dùng đúng địa chỉ hiện hành; không rò dữ liệu giữa người dùng và không nhớ lại dữ liệu đã xóa.'],
    ['Không nâng nội dung từ tài liệu hay tool thành policy bền vững.','Một lần nhớ đúng tên chưa kiểm được temporal reasoning, cập nhật hay abstention.'],
    [['Context window lớn có thay memory không?','Không: giới hạn context và lưu dữ liệu qua phiên là hai vấn đề khác nhau; vẫn cần chọn, cập nhật và phân quyền dữ liệu.'],['Lúc nào ghi nền có thể gây lỗi?','Khi lượt kế tiếp cần fact mới nhưng job chưa commit, hoặc retry tạo trùng và conflict không được giải quyết.'],['Đo memory bằng gì ngoài recall?','Đo mức hữu ích với task, cập nhật/xóa đúng, isolation, token, latency và lỗi từ memory độc hoặc cũ.']]);

  O(18,
    'Production RAG là chẩn đoán lỗi theo tầng offline và online, rồi sửa tầng có bằng chứng. Đổi model không sửa được tài liệu parse sai hoặc chunk không được retrieve.',
    'Lần theo một câu trả lời sai từ corpus đến context và chọn thí nghiệm sửa pipeline có kiểm soát.',
    [['Chuẩn bị dữ liệu · offline','Parse tài liệu, giữ cấu trúc, quyền và version; chọn chunking theo loại dữ liệu.','Chunk có nguồn và metadata'],['Xây index · offline','Tạo biểu diễn tìm kiếm, cập nhật cả upsert lẫn delete và chuẩn bị đường chuyển index.','Index truy vấn được'],['Retrieve · online','Biến đổi query khi cần; kết hợp sparse/dense và lấy tập ứng viên đủ rộng.','Ứng viên có liên quan'],['Rerank và tạo context','Reranker (bộ xếp hạng lại) chọn evidence phù hợp trong budget; kiểm quyền và độ mới.','Context có thứ tự và nguồn'],['Generate và đóng vòng','Sinh câu trả lời có grounding, đánh giá từng tầng cùng outcome; dùng lỗi để sửa ingestion hoặc retrieval.','Câu trả lời và phép đo']],
    [['Error tree offline/online','Lần ngược từ lỗi quan sát được','Nếu đáp án thiếu ngoại lệ: kiểm corpus có ngoại lệ không, parse có giữ không, chunk có chứa không, retrieve có lấy không, model có dùng không.'],['Hierarchical chunking','Chunking là quyết định theo cấu trúc','Chunking (chia tài liệu thành đoạn) cần giữ ngữ cảnh cần thiết; hierarchical chunking (chia theo phân cấp) có thể tìm đoạn nhỏ rồi bổ sung phần cha.'],['Hybrid và RRF','Nhiều tín hiệu tìm kiếm bổ sung nhau','Hybrid retrieval (truy xuất kết hợp) dùng tín hiệu từ khóa và vector; RRF (gộp thứ hạng nghịch đảo) gộp ranking, không đòi score các hệ phải cùng thang đo.'],['Retrieve rộng rồi rerank','Recall trước, precision sau','Retrieve đủ rộng giúp giảm bỏ sót; rerank chọn lại thứ tự. Tăng top-k không giải quyết tài liệu thiếu hoặc parsing sai.'],['CDC upsert và delete','Index là bản sao cần đồng bộ','CDC (ghi nhận thay đổi dữ liệu) phải truyền cả sửa và xóa; metadata version, alias và cache invalidation bảo vệ tính hiện hành.']],
    ['Phân biệt late chunking, contextual enrichment, RAPTOR và Q&A giả lập theo lỗi cần giải.','Biết khi nào cần ColBERT, SPLADE hoặc retrieval đa phương thức; đo thêm chi phí và latency.'],
    ['Tối ưu vector compression và các kiểu index khi workload thực chứng minh bottleneck.'],
    ['Bot trả thiếu điều khoản loại trừ dù tài liệu gốc có nội dung đó.',['Tìm điều khoản trong text đã parse và chunk.','Kiểm tập ứng viên trước/sau rerank bằng cùng query.','Chỉ thay một thành phần rồi chạy lại bộ eval có case ngoại lệ.'],'Recall phần ngoại lệ và câu trả lời tăng, không gây regression lớn về nguồn, quyền hoặc latency.'],
    ['Điểm grounding cao không chứng minh tài liệu đang có hiệu lực.','Đổi chunking, embedder và reranker cùng lúc không chỉ ra thành phần nào tạo cải thiện.'],
    [['Khi nào tăng top-k không giúp?','Khi thông tin không có trong corpus/index, bị parse sai hoặc query/biểu diễn không tìm được nó.'],['Blue-green index có vai trò gì?','Xây và kiểm index mới song song, rồi chuyển alias có kiểm soát và giữ đường rollback.'],['Vì sao đo cả component lẫn E2E?','Metric từng tầng giúp định vị lỗi; outcome toàn luồng mới cho biết người dùng có hoàn thành tác vụ hay không.']]);

  O(19,
    'GraphRAG dùng quan hệ có cấu trúc để lấy bằng chứng qua nhiều bước. Nó hữu ích khi câu hỏi cần nối quan hệ mà tìm đoạn tương tự chưa đủ.',
    'Vẽ được đường từ entity đến quan hệ, traversal và câu trả lời có provenance; biết khi nào graph không đáng chi phí.',
    [['Đặt schema','Xác định loại entity, relation, chiều cạnh và ràng buộc theo câu hỏi cần trả lời.','Ontology có phạm vi'],['Trích xuất và hợp nhất','Nhận diện thực thể, giải tên đồng nghĩa và liên kết đúng entity; giữ nguồn và thời gian.','Graph có provenance'],['Tìm seed','Seed (node bắt đầu) phải được nhận diện đúng; có thể tìm qua entity hoặc chunk.','Điểm bắt đầu ít mơ hồ'],['Duyệt graph có giới hạn','Traversal (duyệt quan hệ) theo số hop, loại cạnh, quyền và budget; kết hợp vector khi cần.','Subgraph liên quan'],['Văn bản hóa và trả lời','Giữ hướng, đường quan hệ và nguồn khi chuyển subgraph thành context cho model.','Đáp án có đường chứng minh']],
    [['Node edge triple và hướng','Một quan hệ có chủ thể và chiều','Triple (bộ ba chủ thể–quan hệ–đối tượng) giúp biểu diễn ai liên quan tới ai; đảo chiều cạnh có thể đổi nghĩa.'],['Ontology và governance','Schema trước khi xây quá nhiều cạnh','Ontology (mô hình khái niệm và quan hệ) quy định loại dữ kiện hợp lệ; governance giữ version, owner và quy tắc cập nhật.'],['Extraction resolution linking','Tên giống không có nghĩa cùng entity','Entity resolution (hợp nhất các bản ghi cùng thực thể) và disambiguation (giải nhập nhằng) quyết định seed và đường nối có đúng không.'],['Traversal có giới hạn','Duyệt đúng thay vì duyệt hết','Giới hạn hop, fan-out, thời gian và kiểu cạnh để tránh graph explosion và context nhiễu; chọn BFS/DFS theo mục tiêu.'],['Textualization giữ bằng chứng','Đường quan hệ phải sống tới câu trả lời','Textualization (biến graph thành văn bản) cần giữ hướng cạnh, nguồn và thời gian; một chuỗi tên node không đủ chứng minh claim.']],
    ['Phân biệt property graph và RDF; query language gắn với mô hình dữ liệu.','So hybrid graph–vector với baseline flat RAG trên câu hỏi thật và đo riêng indexing/query cost.'],
    ['Community summarization và tối ưu truy vấn khi graph đủ lớn và use case cần tổng hợp toàn cục.'],
    ['Câu hỏi hỏi công ty nào gián tiếp chịu ảnh hưởng khi một nhà cung cấp bị gián đoạn.',['Giải đúng entity nhà cung cấp và loại quan hệ phụ thuộc.','Duyệt các cạnh cần thiết trong giới hạn hop, giữ nguồn/thời gian.','Tách quan hệ được xác minh với suy luận chưa đủ bằng chứng.'],'Mỗi kết luận có đường quan hệ đúng chiều và nguồn; so độ đúng/chi phí với RAG thường.'],
    ['Graph xây từ extraction sai vẫn có thể cho câu trả lời rất có vẻ hợp lý.','Nhiều cạnh hơn không tự làm câu trả lời tốt hơn.'],
    [['Câu hỏi nào đáng thử GraphRAG?','Câu hỏi cần nối nhiều quan hệ, entity hoặc truy nguồn đường phụ thuộc; vẫn cần so baseline.'],['Vì sao seed sai nguy hiểm?','Các bước traversal sau có thể đúng kỹ thuật nhưng chạy trên thực thể khác, tạo bằng chứng cho câu hỏi khác.'],['Cần giữ gì khi đưa graph vào model?','Entity identity, hướng/loại cạnh, đường nối, provenance, thời gian và các giới hạn của bằng chứng.']]);

  O(20,
    'Nhiều agent chỉ đáng dùng khi tách được việc hoặc context và lợi ích vượt chi phí phối hợp. Mỗi agent thêm một nguồn lỗi, độ trễ và quyền cần kiểm soát.',
    'Chọn topology theo dependency, thiết kế handoff rõ ràng và chứng minh lợi ích so single-agent.',
    [['Phân rã task','Vẽ phần phụ thuộc và phần độc lập; xác định một owner cho kết quả cuối.','Dependency graph'],['Chọn cách phối hợp','Chọn router, supervisor, pipeline, parallel hoặc debate theo đặc tính task.','Topology có lý do'],['Đặt contract và context','Mỗi worker nhận brief, output schema và quyền tối thiểu; shared state có quy tắc ghi.','Handoff rõ ràng'],['Chạy có kiểm soát','Giới hạn pool, deadline và retry; quy định cách xử lý worker lỗi hoặc kết quả thiếu.','Kết quả thành phần có trạng thái'],['Tổng hợp và đánh giá','Join theo dependency, kiểm evidence và so quality/cost/latency với baseline.','Kết luận có phép so công bằng']],
    [['Khi nào cần nhiều agent','Phân rã trước khi thêm vai','Một task tuần tự, context nhỏ và tool rõ có thể hợp single-agent hơn. Tên vai không chứng minh chuyên môn hoặc tạo ra tính độc lập.'],['Supervisor và handoff','Điều phối cần điều kiện chuyển việc','Supervisor (bộ điều phối) phải biết chọn ai, khi nào kết thúc và xử lý kết quả thiếu; handoff (bàn giao tác vụ) cần đủ dữ liệu và trạng thái.'],['Shared state và một người ghi','Một kết quả cần owner rõ','Shared state (trạng thái dùng chung) cần schema, merge rule và quyền ghi để tránh ghi đè hoặc hai agent cùng sửa một artifact.'],['Async pools và deadline','Song song hóa trong giới hạn','Concurrency (số tác vụ chạy đồng thời) phải phù hợp hạn mức, tài nguyên và deadline; gather không tự giải mọi lỗi riêng lẻ.'],['Debate và lỗi tương quan','Đồng thuận không thay sự thật','Debate (tranh biện giữa các agent) có thể phát hiện lỗi, nhưng nhiều agent cùng dùng một nguồn sai vẫn có thể đồng thuận sai.']],
    ['Biết context firewall, progressive skill loading và event log để giảm drift trong task dài.','Giữ evaluator ngoài quyền sửa khi cho agent tự phát triển playbook; đo lỗi theo MAST và trace.'],
    ['Tối ưu heterogeneous model routing và topology động sau khi có benchmark ổn định.'],
    ['Researcher chưa xong nhưng Writer đã xuất báo cáo; Analyst ghi đè shared state.',['Sửa dependency và điểm join trước khi tổng hợp.','Đặt schema output và owner ghi cho từng phần state.','Giới hạn deadline, đánh dấu partial result và kiểm nguồn của báo cáo.'],'Báo cáo không che dữ kiện thiếu; so lại cùng task với single-agent về chất lượng, thời gian và chi phí.'],
    ['Không lấy một trace đẹp làm bằng chứng đáp án đúng.','Đừng nhầm permissions (quyền được phép) với sandbox (môi trường giới hạn tác động).'],
    [['Khi nào parallel không nhanh hơn?','Khi các phần phụ thuộc tuần tự hoặc overhead, rate limit và tổng hợp lớn hơn phần thời gian tiết kiệm.'],['Brief cho worker cần gì?','Mục tiêu, đầu vào, output contract, phạm vi quyền, ràng buộc và tiêu chí hoàn tất.'],['So single và multi thế nào cho có ý nghĩa?','Dùng cùng task, nhãn và điều kiện budget; lưu per-case results và báo cả failure modes.']]);

  O(21,
    'Fine-tuning thay trọng số để học hành vi hoặc phân bố dữ liệu. Thành công phụ thuộc dữ liệu, cách tính loss và eval, không chỉ chọn rank LoRA.',
    'Quyết định có nên tune, chuẩn bị dữ liệu đúng, dự toán bộ nhớ và đánh giá model đã xuất bằng tác vụ thật.',
    [['Chứng minh nhu cầu','So prompt/RAG/baseline trước; xác định hành vi cần học và mục tiêu đo được.','Lý do tune và baseline'],['Chuẩn bị dữ liệu','Tách train/eval, kiểm quyền, format hội thoại, chat template và phần token cần tính loss.','Dataset có version'],['Chọn phương pháp','Chọn full fine-tuning hoặc PEFT theo capacity, GPU memory và ràng buộc serving.','Cấu hình khả thi'],['Train và chẩn đoán','Theo dõi loss, memory, gradient và ví dụ sinh; kiểm masking, packing và EOS khi có lỗi.','Checkpoint cùng run config'],['Eval và phục vụ','So held-out tasks, kiểm regression và artifact sau merge/quantization; triển khai có rollback.','Model hữu ích trong hệ đích']],
    [['CPT SFT và distillation','Mục tiêu train quyết định dữ liệu','CPT (tiếp tục pre-training) học phân bố miền; SFT (tinh chỉnh có giám sát) học từ cặp chỉ dẫn–đáp án; distillation (chưng cất) học tín hiệu từ model khác.'],['Loss masking và labels','Model học ở token nào?','Loss masking (che token khỏi loss) thường tránh thưởng việc lặp lại phần prompt; phải kiểm template và nhãn thực tế thay vì chỉ nhìn text đẹp.'],['Cơ chế và tham số LoRA','Adapter học phần cập nhật trọng số','LoRA (tinh chỉnh bằng ma trận hạng thấp) học hai ma trận nhỏ thay vì cập nhật toàn bộ ma trận gốc. Base bị đóng băng vẫn tham gia forward/backprop để tính gradient cho adapter.'],['Bộ nhớ full fine-tuning','Bộ nhớ không chỉ có weights','Cần tính weights, gradients, optimizer states và activations; mixed precision, batch, chiều dài chuỗi và sharding làm dự toán thay đổi.'],['QLoRA và lượng tử hóa','Giảm memory không xóa mọi đánh đổi','QLoRA (LoRA trên base được lượng tử hóa) giảm phần lưu base khi train; chất lượng và tốc độ serving vẫn phải đo sau export theo runtime thật.'],['Eval và chat-template debugging','Loss giảm chưa đủ','Held-out evaluation (đánh giá trên tập giữ riêng) đo khả năng làm task và regression. Sai chat template/EOS có thể làm model sinh lỗi dù loss có vẻ tốt.']],
    ['Hiểu rank, target modules, learning rate và batch liên quan tới capacity và độ ổn định.','Biết sequence packing cần giữ ranh giới mẫu; hiểu checkpointing, ZeRO/FSDP và offload giải phần bộ nhớ nào.'],
    ['Thử các biến thể adapter, kernel hoặc model merging khi có bottleneck cụ thể và bộ eval đủ tốt.'],
    ['Model train loss giảm nhưng lúc chat chỉ lặp prompt rồi không dừng.',['Kiểm tokens, role markers, labels và vùng loss trên một mẫu thật.','Đối chiếu chat template, EOS và generation config giữa train và inference.','So baseline trên bộ task riêng trước và sau sửa.'],'Model trả đúng vai, dừng đúng và tăng task success; kiểm thêm dữ liệu riêng tư và regression.'],
    ['Fine-tuning không phải cách đảm bảo model luôn nhớ đúng dữ liệu mới thay đổi.','Synthetic data cần quyền sử dụng, lọc chất lượng và đánh giá độc lập để tránh khuếch đại lỗi.'],
    [['Vì sao giảm loss mà task vẫn kém?','Loss có thể tối ưu sai phần token, data không hợp task, overfit hoặc inference dùng sai template; cần kiểm dữ liệu và held-out outputs.'],['LoRA rank tăng luôn tốt hơn không?','Không. Capacity tăng cũng tăng chi phí và nguy cơ overfit; phải đo với dữ liệu, target modules và budget cụ thể.'],['Cần kiểm gì sau merge/export?','Cùng tokenizer/template, model load đúng, output và task metrics không regression, memory/latency phù hợp runtime và license/privacy được đáp ứng.']]);

  O(22,
    'Alignment học cách ưu tiên hành vi mong muốn từ tiêu chí và phản hồi. Tiêu chí sai hoặc verifier yếu có thể làm model học cách được điểm thay vì làm việc đúng.',
    'Theo được chuỗi tiêu chí → preference data → objective train → đánh giá hành vi, và phân biệt DPO, ORPO với RL có verifier.',
    [['Định nghĩa điều tốt','Viết rubric và ranh giới an toàn, tách correctness khỏi hình thức.','Tiêu chí có ví dụ'],['Tạo phản hồi','Tạo preference pairs hoặc tín hiệu reward đáng tin; giữ cùng prompt và kiểm nhãn.','Dữ liệu phản hồi sạch'],['Chọn objective','Chọn DPO/ORPO hay một dạng RL theo dữ liệu, hạ tầng và tính kiểm chứng của task.','Mục tiêu tối ưu rõ'],['Train có kiểm soát','Theo dõi drift, length hacking và các chiều reward; giữ eval ngoài train.','Biến thể có version'],['Kiểm hành vi độc lập','Đo task quality, safety, refusal và khả năng tổng quát; dùng lỗi để sửa rubric/data.','Cải thiện được xác nhận']],
    [['SFT và alignment','Biết bắt chước khác biết ưu tiên','SFT học đáp án mẫu; preference alignment (điều chỉnh theo ưu tiên) học chọn hành vi được đánh giá tốt hơn. Cả hai không tự đảm bảo factual correctness.'],['DPO và reference log-ratio','DPO dùng so sánh với reference','DPO (tối ưu ưu tiên trực tiếp) học tăng ưu tiên chosen so với rejected tương đối với reference model (mô hình tham chiếu), không cần train reward model riêng theo pipeline RLHF truyền thống.'],['ORPO objective kết hợp','ORPO kết hợp hai mục tiêu','ORPO (tối ưu ưu tiên bằng tỷ số odds) kết hợp loss SFT với phần ưu tiên; không nên mô tả nó là chỉ bỏ reference khỏi một pipeline bất kỳ.'],['Preference pair chất lượng','Nhãn cần phân biệt đúng điều muốn học','Một cặp cần cùng ngữ cảnh và lý do ưu tiên nhất quán; nếu chosen luôn dài hơn thì model có thể học độ dài thay vì chất lượng.'],['GRPO bỏ critic chứ không bỏ mọi reward','RL vẫn cần tín hiệu đáng tin','GRPO (tối ưu policy tương đối theo nhóm) không dùng critic/value model theo cách PPO thông thường; RLVR (RL với reward kiểm chứng được) phụ thuộc verifier và vẫn có thể bị khai thác.']],
    ['Hiểu beta/regularization theo objective cụ thể; không suy chất lượng chỉ từ reward margin.','Biết SimPO, KTO, Constitutional AI và RLAIF giải bài toán phản hồi nào; judge cũng cần hiệu chuẩn.'],
    ['Iterative preference optimization và model merging sau khi có kiểm soát drift và held-out eval.'],
    ['Sau alignment, câu trả lời dài hơn và judge cho điểm cao, nhưng thêm nhiều fact sai.',['Audit cặp preference và rubric xem có thưởng độ dài hay phong cách.','Tách correctness, grounding và verbosity trong eval độc lập.','Sửa nhãn/tiêu chí rồi so lại với baseline cùng prompts.'],'Human review và task metrics xác nhận nội dung tốt hơn; reward training đơn lẻ không đủ kết luận.'],
    ['GRPO bỏ critic không có nghĩa mọi reward model hay reward signal đều biến mất.','Verifier pass không đủ nếu verifier chỉ kiểm một phần dễ bị lách của task.'],
    [['DPO có cần reward model riêng không?','Trong cách dùng DPO chuẩn, objective học trực tiếp từ preference pairs và reference; khác pipeline train reward model rồi chạy PPO.'],['Chosen tốt hơn cần xét điều gì?','Cùng prompt/context, đúng nội dung, tuân ràng buộc, nhãn nhất quán và không chỉ có hình thức hấp dẫn hơn.'],['Alignment có sửa được mọi hallucination không?','Không. Cần dữ liệu, grounding, verification và eval; alignment chủ yếu thay xu hướng hành vi theo tín hiệu tối ưu.']]);

  O(23,
    'Orchestration biến quyết định của model thành một luồng có state, điểm dừng và khả năng phục hồi. Phần chắc chắn nên được kiểm soát rõ; phần cần suy luận được cấp quyền có giới hạn.',
    'Giải thích cách state đi qua graph, checkpoint, interrupt và resume mà không lặp tác động ngoài ý muốn.',
    [['Đặt state và contract','Định nghĩa dữ liệu node đọc/ghi, reducer và quyền của các bước.','Schema state'],['Chọn đường chạy','Edge, conditional routing hoặc lệnh điều phối quyết định bước kế tiếp; giới hạn vòng lặp.','Graph có điểm kết thúc'],['Thực thi và checkpoint','Lưu tiến trình theo thread; hiểu điểm commit và phần việc đã hoàn tất.','State có thể phục hồi'],['Pause và resume','Interrupt (tạm dừng chờ quyết định) phải gắn đúng thread và payload; node có thể chạy lại khi resume.','Quyết định khớp hành động'],['Stream và kiểm outcome','Phân biệt sự kiện hiển thị với bước đã commit; kiểm cả artifact và tác động ở hệ đích.','Kết quả được xác minh']],
    [['StateGraph node và edge','Graph biểu diễn luồng và state','StateGraph (đồ thị trạng thái) tổ chức node và edge. Node trả cập nhật state; routing cần bám contract thay vì chỉ dựa tên agent.'],['Super-step và reducer','Ghi đồng thời cần quy tắc hợp nhất','Reducer (hàm hợp nhất cập nhật) quyết định cách các nhánh cùng ghi state được kết hợp; phép cộng, append hay ghi đè cho kết quả khác nhau.'],['Durability và checkpointer','Phục hồi có ranh giới commit','Durability (khả năng giữ tiến trình sau sự cố) phụ thuộc cấu hình và backend; checkpointer không tự hoàn tác mọi side effect ngoài graph.'],['Interrupt và replay node','Resume có thể chạy lại code','Code trước interrupt có thể được chạy lại. Side effect (tác động ra hệ ngoài) cần idempotency hoặc vị trí thực thi được thiết kế phù hợp.'],['Thread state và cross-thread Store','Hai phạm vi lưu trữ khác nhau','State của thread phục vụ lượt công việc; Store lưu dữ liệu qua nhiều thread theo namespace và policy. Time travel/fork không phải undo dữ liệu ngoài hệ.']],
    ['Biết Send/Command dùng để phân phối và điều phối trong graph; giới hạn recursion không đồng nghĩa số API calls.','Hiểu bốn thao tác context của Deep Agents: ghi, chọn, nén và tách context; backend quyết định độ bền.'],
    ['Compile workflow, topology tự học và benchmark harness khi đã có baseline, contract và evaluator đáng tin.'],
    ['Graph gửi thông báo trước interrupt; sau resume gửi lại lần thứ hai.',['Xem node được replay và đoạn code trước điểm pause.','Đặt idempotency key hoặc tách bước gửi theo trạng thái commit.','Test crash/resume với cùng thread và quyết định trùng.'],'Một hành động logic chỉ tạo một thông báo; state và external effect nhất quán theo contract.'],
    ['Checkpoint không biến toàn hệ thành giao dịch exactly-once.','HTTP 200 hoặc token stream xong chưa chứng minh validator và business outcome đã đạt.'],
    [['Reducer cần thiết ở đâu?','Khi nhiều cập nhật cùng vào một key hoặc cần tích lũy state; phải chọn phép hợp nhất phù hợp ý nghĩa dữ liệu.'],['Fork state có hoàn tác email đã gửi không?','Không. Fork tạo nhánh tiến trình; side effect ở hệ ngoài cần quy trình bù hoặc xử lý riêng.'],['Khi nào dùng hybrid shell?','Khi cần code cưỡng chế contract, quyền, budget và validation quanh các bước model được phép suy luận.']]);

  O(24,
    'Đánh giá cho biết lỗi ở đâu và có đáng phát hành hay không; guardrails chặn hành vi tại đúng ranh giới. Một điểm judge cao không thay dữ liệu chuẩn và kiểm tra hành động thật.',
    'Thiết kế eval nhiều tầng, đọc đúng RAG metrics và đặt guardrail có đo false pass/false block.',
    [['Định nghĩa task và risk','Xác định outcome, nguồn chuẩn và những lỗi không thể chấp nhận.','Rubric và bộ case'],['Đo từng tầng','Tách retrieval, generation và hành động; xác định input của từng metric.','Per-case scores'],['Hiệu chuẩn judge','So judge với người trên mẫu có nhãn; kiểm bias theo vị trí, độ dài và phong cách.','Sai số của evaluator'],['Đặt guardrails','Kiểm input, retrieval, execution và output theo policy; quyền tool được cưỡng chế trước hành động.','Các gate đúng boundary'],['Chặn regression','Đưa lỗi thực vào CI eval; review case xấu và cân usefulness với safety.','Release decision có bằng chứng']],
    [['Component và end-to-end eval','Đo đúng tầng và outcome','Component evaluation (đánh giá thành phần) định vị lỗi; E2E evaluation (đánh giá toàn luồng) kiểm người dùng có hoàn thành task đúng hay không.'],['Faithfulness','Bám nguồn khác đúng sự thật','Faithfulness (mức claim được context hỗ trợ) có thể cao khi context sai hoặc cũ; cần kiểm nguồn và correctness riêng.'],['Context recall','Đủ bằng chứng và xếp đúng bằng chứng','Context recall (độ phủ thông tin cần theo reference) khác context precision (độ chính xác của context/ranking theo metric). Phiên bản metric có thể cần inputs khác nhau.'],['Calibration và tiered judge','Judge cũng là thành phần có lỗi','Calibration (hiệu chuẩn) dùng nhãn người và case đại diện để đo false pass/false fail; case khó có thể cần judge mạnh hơn hoặc người review.'],['Guardrail bốn trục nhiều lớp','Chặn đúng và giữ yêu cầu hợp lệ','Guardrail (lớp kiểm soát hành vi) cần phân biệt topical, safety, security và compliance; output moderation không thay authorization của tool.']],
    ['Biết bias của pairwise judge, hạn chế consistency/NLI/semantic entropy và rủi ro synthetic eval.','Test indirect injection qua tool/RAG và memory poisoning qua nhiều lượt; đo cả over-refusal.'],
    ['Tối ưu judge theo cost tiers hoặc detector chuyên biệt sau khi đã có calibration theo domain.'],
    ['RAGAS tốt nhưng agent dùng policy cũ và thực hiện thao tác vượt quyền.',['Kiểm version nguồn và outcome thật, tách lỗi retrieval/generation/action.','Đặt auth tại execution boundary trước side effect.','Bổ sung stale-source, wrong-action và allowed-request cases vào gate.'],'Case nguy hiểm bị chặn, câu hỏi hợp lệ vẫn xử lý; người review tái hiện được quyết định từ artifact.'],
    ['Không coi synthetic labels hoặc LLM judge là ground truth tuyệt đối.','Chặn nhiều nhất không đồng nghĩa guardrail tốt nhất.'],
    [['Faithfulness cao nhưng đáp án sai có thể xảy ra không?','Có: answer có thể bám một context sai hoặc đã hết hiệu lực.'],['Một judge cần được kiểm định thế nào?','Dùng nhãn người, case đại diện và khó; xem confusion theo failure mode, kiểm bias và hiệu chuẩn lại khi model/rubric đổi.'],['Vì sao cần guard trước tool execution?','Vì kiểm output sau đó không ngăn được side effect trái quyền đã xảy ra.']]);

  O(25,
    'Reliability giữ lỗi trong giới hạn về thời gian, chi phí và phạm vi ảnh hưởng. Retry, breaker, fallback và cache giải các lỗi khác nhau, cần phối hợp theo contract.',
    'Thiết kế một request path có timeout, retry chọn lọc, ngắt lỗi lan và cache đúng quyền/độ tươi.',
    [['Đặt mục tiêu','Chọn SLI và SLO theo trải nghiệm người dùng, không chỉ trạng thái HTTP.','Mức dịch vụ cần giữ'],['Phân loại lỗi','Phân biệt lỗi tạm thời, request sai, quá tải và chất lượng suy giảm im lặng.','Policy theo loại lỗi'],['Giới hạn tác động','Áp timeout, retry có backoff/jitter, bulkhead và circuit breaker theo dependency.','Lỗi không lan vô hạn'],['Fallback và cache','Chỉ dùng kết quả thay thế/cũ khi contract cho phép; giữ quyền, freshness và semantics.','Trải nghiệm suy giảm có kiểm soát'],['Đo và diễn tập','Theo dõi burn rate, trace và cost; inject lỗi để kiểm đường phục hồi.','Bằng chứng resilience']],
    [['Retry backoff và jitter','Retry phải có điều kiện dừng','Backoff (giãn khoảng thử lại) và jitter (thêm ngẫu nhiên) giảm bão request; tôn trọng Retry-After, deadline và tránh nhiều tầng retry nhân nhau.'],['Circuit breaker ba trạng thái','Ngắt dependency đang lỗi','Circuit breaker (bộ ngắt mạch) chuyển closed/open/half-open để fail fast rồi probe có giới hạn; nó không sửa request sai.'],['Half-open probe và state phân tán','Phạm vi state quyết định hành vi','Mỗi instance giữ breaker riêng có thể trip khác nhau; half-open cần hạn số probe để tránh đồng loạt dồn tải trở lại.'],['Idempotency khi retry action','Lặp request không được nhân tác động','Idempotency (gọi lặp vẫn cùng một tác động logic) bảo vệ thao tác ghi khi response bị mất và caller không biết request trước đã thành công hay chưa.'],['TTL invalidation và ACL cache','Cache là một bản sao có policy','Cache key phải xét identity/quyền, version và độ tươi; semantic cache (cache theo nghĩa gần nhau) có thể trả nhầm intent.']],
    ['Phân biệt SLI (chỉ số dịch vụ), SLO (mục tiêu) và SLA (cam kết); theo dõi error budget/burn rate.','Hiểu timeout, bulkhead và hedging có chi phí và phạm vi tác động khác nhau; fallback phải giữ contract.'],
    ['Tối ưu gateway, cache thresholds và distributed breaker dựa trên tải thật, không sao chép ngưỡng minh họa.'],
    ['Provider lỗi; tám instance cùng retry rồi đẩy chi phí và latency tăng đột biến.',['Đọc trace để tìm các tầng retry và nhóm lỗi thực.','Chọn một owner retry, deadline tổng và breaker theo dependency; giới hạn half-open probes.','Diễn tập timeout/429/5xx, kiểm fallback và idempotency của action.'],'SLO và cost nằm trong budget đã định; case ghi không bị lặp và lỗi request sai không bị retry vô ích.'],
    ['Không tự động retry mọi 4xx hoặc mọi hành động ghi.','Cache có hit rate cao vẫn có thể rò quyền hoặc trả dữ liệu cũ nguy hiểm.'],
    [['Retry và breaker khác nhau thế nào?','Retry thử lại một lỗi có khả năng phục hồi trong budget; breaker tạm ngắt dependency đang lỗi để hạn chế tải và lỗi lan.'],['Vì sao cần idempotency khi timeout?','Timeout không cho biết server đã commit hay chưa; retry không có key có thể tạo tác động lặp.'],['Semantic cache nguy hiểm khi nào?','Hai câu gần nghĩa về vector nhưng khác user/quyền/thời gian/điều kiện nghiệp vụ có thể cần đáp án khác.']]);

  O(26,
    'Model đề xuất tool call; ứng dụng hoặc server mới thực thi. MCP chuẩn hóa cách khám phá và sử dụng công cụ, còn quyền và business validation vẫn thuộc hệ thống.',
    'Vẽ được đường host → client → server → API và kiểm lỗi ở từng ranh giới contract, auth và output.',
    [['Model đề xuất','Cung cấp tool schema để model chọn tên và tham số phù hợp yêu cầu.','Tool call có cấu trúc'],['Host kiểm quyền','Kiểm schema, policy, consent cần thiết và budget trước execution.','Call được phép chạy'],['Client kết nối server','MCP client khám phá capability và gửi request theo transport đã cấu hình.','Request đúng server/version'],['Server gọi nghiệp vụ','Server validate, thực thi API/DB trong scope và trả kết quả có contract.','Tool result có trạng thái'],['Model dùng observation','Ghép kết quả đúng call ID; model trả lời hoặc tiếp tục vòng có giới hạn.','Kết quả được kiểm chứng']],
    [['Model đề xuất app thực thi','Function calling là đề xuất có cấu trúc','Function calling (model sinh lời gọi hàm) không có nghĩa model tự chạy code hoặc tự được cấp quyền. Host quyết định có thực thi hay không.'],['Host client server MCP','Ba vai trò khác nhau','MCP (giao thức ngữ cảnh cho model) có host chứa ứng dụng AI, client quản lý kết nối và server công bố capability/cung cấp chức năng.'],['Tools resources prompts','Ba loại capability','Tools là thao tác được gọi, resources là dữ liệu để đọc, prompts là mẫu tương tác. Tool cũng có thể chỉ đọc; phân loại này không tự quyết định quyền.'],['MCP authentication authorization','Biết ai gọi khác được làm gì','Authentication (xác thực danh tính) khác authorization (cấp quyền hành động). Khám phá được tool trong registry không có nghĩa được phép dùng.'],['Versioning và deprecation','Output cũng là contract','Đổi output có thể làm client cũ hỏng dù input schema không đổi; cần version, adapter hoặc lộ trình ngừng hỗ trợ có test.']],
    ['Hiểu stdio chạy với quyền process và remote transport cần auth; không mặc định local là an toàn.','Biết async I/O, adapter framework, healthcheck và business call kiểm những tầng khác nhau.'],
    ['Registry và tool ecosystems khi cần chia sẻ nhiều server; app nhỏ có thể chưa cần thêm protocol/server.'],
    ['Server remote healthcheck xanh nhưng client không gọi được tool mới.',['Kiểm đúng server/version và discovery list.','Kiểm auth, scope và schema request/response ở transport thực.','Gọi một business case hợp lệ và một case ngoài quyền, giữ call IDs để trace.'],'Tool chạy E2E với dữ liệu đúng; lỗi quyền và client cũ được xử lý đúng contract.'],
    ['Không thực thi tool chỉ vì model đề xuất tên và JSON hợp lệ.','Đăng ký một server stdio lạ đồng nghĩa chạy code của nó với quyền process.'],
    [['MCP có thay REST API không?','Không bắt buộc. MCP server thường bọc REST/API/DB sẵn có để cung cấp giao diện chuẩn cho client AI.'],['Tool result cần ghép call ID để làm gì?','Để model và host biết observation thuộc lời gọi nào, nhất là khi có nhiều call.'],['Healthcheck xanh chứng minh được gì?','Chỉ tầng mà healthcheck thực sự kiểm; chưa chắc auth, discovery, business execution và output parsing đều đúng.']]);

  O(27,
    'Con người cần can thiệp theo rủi ro và mức không chắc, với đủ bằng chứng để quyết định. Một nút Approve không bảo vệ được nếu duyệt sai payload hoặc tác động đã xảy ra.',
    'Thiết kế một approval loop bền vững, gắn đúng hành động, có reject/timeout và audit rõ ràng.',
    [['Đánh giá action','Xét tác động, khả năng hoàn tác, quyền và chi phí của lỗi.','Risk policy'],['Chọn tuyến xử lý','Auto, clarification, approval hoặc escalation theo hard rules và uncertainty đã hiệu chuẩn.','Điểm can thiệp cần thiết'],['Pause và trình bằng chứng','Lưu checkpoint; hiển thị action card với payload/diff, nguồn và tác động.','Quyết định có đủ ngữ cảnh'],['Nhận và kiểm quyết định','Gắn người duyệt với đúng version hành động; xử lý reject, sửa, timeout và request trùng.','Quyết định hợp lệ'],['Execute và học lại','Thực thi đúng payload đã duyệt, log audit và đo chất lượng quyết định.','Outcome cùng audit trail']],
    [['HITL và human-on-the-loop','Can thiệp trực tiếp khác giám sát','HITL (con người tham gia trực tiếp vào bước xử lý) thường chặn tại điểm cần quyết định; human-on-the-loop (con người giám sát luồng) theo dõi và có thể can thiệp theo policy.'],['Hard rules và confidence routing','Risk không bị confidence ghi đè','Confidence (mức tự tin) cần hiệu chuẩn và không đồng nhất correctness. Hard rules như hành động vượt quyền vẫn chặn dù model rất tự tin.'],['Approval gắn payload và concurrency','Duyệt đúng phiên bản sẽ thực thi','Approval phải gắn action ID, payload/version và identity; nếu nội dung thay đổi sau duyệt thì cần kiểm lại theo policy.'],['TTL timeout và reviewer vắng mặt','Không phản hồi không phải đồng ý','Cần TTL, owner và tuyến escalation; quá hạn xử lý theo risk, tránh auto-approve hành động nhạy cảm chỉ vì reviewer vắng.'],['Action card diff và evidence','Giảm tải nhận thức cho người duyệt','Hiển thị sẽ đổi gì, ai bị ảnh hưởng, nguồn và lý do cần review; cho sửa/reject và nêu lý do thay vì chỉ hai nút thiếu ngữ cảnh.']],
    ['Biết alert fatigue, batch approval và các trường hợp không nên gộp hành động khác risk.','Đo decision quality, override, thời gian chờ và false escalation; feedback dùng train cần review nhãn.'],
    ['Tăng tự động hóa theo từng nhóm action sau khi đủ dữ liệu, giới hạn rủi ro và cơ chế thu hồi.'],
    ['Người duyệt đồng ý hoàn tiền 100 nghìn nhưng request bị đổi thành 1 triệu trước execution.',['Ràng approval với payload/version đã xem và kiểm integrity trước execute.','Nếu payload thay đổi, invalidate quyết định cũ và yêu cầu review lại.','Giữ idempotency, hạn duyệt và audit danh tính/thời điểm.'],'Chỉ đúng payload được duyệt tạo một tác động; sửa payload hoặc quyết định hết hạn không được tái dùng.'],
    ['Đặt interrupt sau action không bảo vệ được tác động đã diễn ra.','Audit append-only không tự bảo đảm mọi log đều đúng hoặc miễn nhiễm can thiệp.'],
    [['Vì sao logprob không đủ để auto-approve?','Nó mô tả xác suất token theo model, không trực tiếp là xác suất hành động đúng và an toàn theo nghiệp vụ.'],['Action card tối thiểu cần gì?','Payload/diff cụ thể, tác động, nguồn/bằng chứng, risk và các lựa chọn approve/edit/reject kèm identity/version.'],['Reviewer không phản hồi thì làm gì?','Dùng policy TTL/escalation đã định; không mặc định đồng ý đối với action cần approval.']]);

  O(28,
    'Một hệ AI hoàn chỉnh cần nối được dữ liệu, model, hành động, safety và feedback. Chất lượng từng module không tự chứng minh toàn luồng vận hành đúng ngoài thực tế.',
    'Lập một release bundle có contract, E2E evidence, runbook và cách kiểm định phù hợp rủi ro của hệ thực tế.',
    [['Chốt outcome và contract','Xác định đầu vào, kết quả ở hệ đích, quyền và yêu cầu thời gian/safety.','API/state contracts'],['Tích hợp bốn luồng','Nối data, model/decision, safety/control và feedback; kiểm các điểm giao giữa module.','Luồng E2E rõ ràng'],['Benchmark theo risk','Đo outcome lẫn trajectory; dùng simulation, hardware-in-loop hoặc field test theo phạm vi phù hợp.','Evidence có điều kiện'],['Phát hành có kiểm soát','Chuẩn bị config, owner, canary/shadow, rollback và runbook sự cố.','Release bundle'],['Biến lỗi thành dữ liệu','Thu thập lỗi hợp quyền, review/label, đưa vào regression rồi kiểm lại trước rollout.','Vòng cải tiến có gate']],
    [['Integration seams và contracts','Kiểm điểm nối giữa các module','Contract (giao kèo dữ liệu và hành vi) phải bao gồm lỗi, timeout và state chuyển tiếp; mock pass chưa chứng minh external action thật đúng.'],['Outcome trajectory và pass metrics','Đạt một lần khác ổn định qua nhiều lần','Outcome là kết quả cuối; trajectory (chuỗi hành động) cho biết đường thực hiện có đúng quyền và quy trình. Pass@k và thành công qua mọi lần là các câu hỏi xác suất khác nhau.'],['Voice turn-taking và barge-in','Voice có thời gian thực và ngắt lượt','Turn-taking (điều phối lượt nói), VAD (phát hiện hoạt động giọng nói) và barge-in (người dùng ngắt lời hệ thống) cần phối hợp audio buffer và trạng thái task.'],['Real-world system bốn luồng','Model là một phần của hệ vật lý','ADAS, robot, CCTV và GeoAI đều cần dữ liệu, quyết định, safety/control và feedback, nhưng deadline và cách kiểm định khác nhau.'],['Risk-based validation và data flywheel','Chọn phép kiểm theo phạm vi rủi ro','Risk-based validation (kiểm định theo rủi ro) cần test đại diện điều kiện vận hành; data flywheel (vòng cải tiến từ dữ liệu sử dụng) chỉ hiệu quả khi lỗi được review, gắn nhãn và tái kiểm.']],
    ['Phân biệt CPS, concurrency và call legs khi dự toán Voice AI; giá/ngưỡng slide chỉ là ví dụ.','Hiểu ODD (phạm vi điều kiện vận hành) của ADAS, edge/event-first của CCTV và slow reasoning–fast control của robot.','GeoAI cần đối chiếu mùa, mây, sensor và alignment trước kết luận thay đổi.'],
    ['Các kỹ thuật robotics/sim-to-real và mô hình thị giác chuyên sâu sau khi hiểu data/control/safety boundaries.'],
    ['Voice agent báo đặt lịch thành công trong transcript nhưng hệ lịch không có booking.',['Trace từ lời người dùng qua tool call tới external state với correlation ID.','Kiểm timeout, retry/idempotency và chỉ báo thành công sau xác nhận hợp lệ.','Thêm case ngắt lời, thiếu slot và API lỗi vào E2E suite.'],'Lịch thật có đúng một booking đúng nội dung; bot không nói đã xong khi backend chưa xác nhận.'],
    ['Không dùng số liệu vendor hay demo như kết quả kiểm định độc lập của hệ mình.','Chỉ có logging chưa hình thành vòng học; chỉ có model accuracy chưa bảo đảm safety hệ thống.'],
    [['Tại sao cần kiểm trajectory khi outcome đúng?','Đường thực hiện có thể vi phạm quyền, lãng phí budget hoặc dùng bằng chứng không hợp lệ dù tình cờ ra kết quả đúng.'],['Release bundle gồm những gì?','Artifact/version, config, eval evidence, owner, API/state contracts, runbook, monitoring và đường rollback theo phạm vi dự án.'],['Khi nào dữ liệu mới thật sự giúp hệ tốt hơn?','Khi được chọn đúng lỗi, xử lý quyền, review nhãn, đưa vào eval/train phù hợp rồi chứng minh cải thiện không gây regression.']]);

  O(1,
    'LLM tạo token dựa trên context và xác suất đã học. Một ứng dụng AI hữu ích cần thêm dữ liệu, công cụ, kiểm chứng và giới hạn vận hành quanh model.',
    'Vẽ được một request LLM và giải thích token, context, giới hạn kiến thức cùng chi phí cơ bản.',
    [['Nhận yêu cầu','Xác định cần phân loại, sinh nội dung hay thực hiện hành động; không mặc định mọi bài toán cần agent.','Loại nhiệm vụ'],['Chuẩn bị context','Gom chỉ dẫn, lịch sử và dữ liệu liên quan trong giới hạn token.','Đầu vào có cấu trúc'],['Model sinh token','Inference (quá trình mô hình tạo kết quả) dùng mẫu đã học để dự đoán token tiếp theo.','Nội dung sinh ra'],['Kiểm chứng','Đối chiếu nguồn, schema hoặc trạng thái hệ đích theo task; xử lý thiếu thông tin.','Kết quả đủ tin cậy'],['Đo vận hành','Ghi usage, latency và lỗi để hiểu chi phí và điểm cần cải thiện.','Thông số của request']],
    [['AI taxonomy','AI, ML và LLM nằm ở đâu?','AI (trí tuệ nhân tạo) là phạm vi rộng; ML (học máy) học mẫu từ dữ liệu; deep learning (học sâu) dùng mạng nhiều tầng. LLM (mô hình ngôn ngữ lớn) là một nhánh, không đại diện mọi hệ AI.'],['Transformer','Token đi qua model thế nào?','Embedding (biểu diễn token bằng vector), thông tin vị trí và attention (cơ chế cân nhắc quan hệ trong context) tạo biểu diễn để dự đoán token.'],['Token & context','Ngân sách context có giới hạn','Token (đơn vị văn bản model xử lý) không luôn trùng một từ; context window giới hạn lượng ngữ cảnh model có thể xử lý. Tokenizer và API quyết định cách tính cụ thể.'],['Training & giới hạn','Học mẫu không đồng nghĩa tra sự thật','Pre-training học phân bố dữ liệu; SFT và alignment hướng hành vi. Hallucination (tạo thông tin không chính xác) vẫn có thể xảy ra, nhất là khi thiếu nguồn mới.'],['API & chi phí','Một request có cả chi phí và độ trễ','Dự toán từ input/output tokens và đơn giá tương ứng; streaming cho thấy phần đầu sớm hơn nhưng không mặc định giảm tổng token hay tổng thời gian.']],
    ['Phân biệt chatbot, workflow và agent theo hành vi hệ thống.','Khi dùng AI sinh code, vẫn chạy, review và kiểm yêu cầu trước phát hành.'],
    ['Chi tiết attention và tối ưu kiến trúc Transformer khi cần đọc sâu model internals.'],
    ['Bot trả một sự kiện mới bằng giọng rất chắc chắn.',['Xác định dữ kiện cần nguồn cập nhật.','Cấp tài liệu/tool phù hợp và yêu cầu câu trả lời có bằng chứng.','Kiểm claim với nguồn; ghi usage và latency.'],'Câu trả lời được nguồn hỗ trợ hoặc nêu rõ thiếu thông tin; không dùng văn phong làm độ tin cậy.'],
    ['Không đồng nhất AI với LLM hoặc mọi LLM app với agent.','Context dài và câu chữ trôi chảy không bảo đảm correctness.'],
    [['Vì sao một từ không luôn bằng một token?','Tokenizer có thể tách từ, âm tiết, ký tự hoặc mảnh code theo cách khác nhau.'],['Model cần dữ liệu mới thì làm gì?','Cấp nguồn cập nhật qua retrieval/tool, kiểm quyền và kiểm chứng đầu ra; tăng tự tin hay temperature không tạo sự thật.'],['Chi phí token cơ bản tính thế nào?','Input tokens nhân giá input cộng output tokens nhân giá output, theo đúng đơn vị giá; cộng các chi phí hệ thống liên quan khi dự toán sản phẩm.']]);

  O(2,
    'Bắt đầu từ quyết định hoặc công việc người dùng cần cải thiện, rồi mới xét AI có phù hợp hay không. Một demo có vẻ thông minh chưa chứng minh giá trị.',
    'Viết problem statement có baseline, dữ liệu, rủi ro, metric và điều kiện go/no-go.',
    [['Khám phá vấn đề','Quan sát ai làm gì, ở đâu mất thời gian hoặc gây lỗi và hiện xử lý thế nào.','Nhu cầu có bằng chứng'],['Định nghĩa đầu ra','Mô tả quyết định cần cải thiện, phạm vi và người chịu tác động.','Problem statement'],['Chọn mức giải pháp','So rule, search, workflow và AI/agent theo tính bất định và mức rủi ro.','Lựa chọn có lý do'],['Chạy thử nhỏ','Lấy dữ liệu đại diện, tạo baseline và kiểm một giả thuyết quan trọng nhất.','Kết quả thí nghiệm'],['Go/no-go','So lợi ích, lỗi, chi phí và điều kiện dữ liệu; dừng hoặc thu hẹp khi chưa đạt.','Quyết định có tiêu chí']],
    [['Discovery','Phân biệt nhu cầu với tính năng','Discovery (khám phá vấn đề) tìm bằng chứng từ workflow và người dùng; câu “cần chatbot” vẫn chưa nói vấn đề gốc.'],['AI fit','AI phù hợp khi nào?','AI fit (mức phù hợp dùng AI) phụ thuộc tính mơ hồ của task, dữ liệu, khả năng đánh giá và chi phí lỗi; việc có API model không đủ.'],['Mức giải pháp','Ưu tiên mức phức tạp cần thiết','Rule hoặc workflow xác định có thể đủ cho nhiệm vụ ổn định; agent có ích khi cần chọn hành động theo quan sát và có cách kiểm soát.'],['Problem statement','Câu mô tả phải đo được','Nêu user, pain point, outcome, phạm vi, baseline, constraints và dữ liệu để tránh biến một ý tưởng thành yêu cầu mơ hồ.'],['Metric & gate','Đặt điều kiện trước khi xem điểm','Metric (chỉ số đo) phải phản ánh giá trị và lỗi; gate (ngưỡng quyết định) cần được chốt theo rủi ro/use case trước khi diễn giải thí nghiệm.']],
    ['Vẽ workflow hiện tại và tương lai, chỉ rõ điểm handoff.','Thêm metric bảo vệ như lỗi nghiêm trọng, quyền riêng tư hoặc tải review bên cạnh metric giá trị.'],
    ['Tối ưu mô hình tài chính chi tiết sau khi chứng minh có nhu cầu và baseline đáng cải thiện.'],
    ['Đội muốn làm chatbot để giảm tải hỗ trợ nhưng chưa biết ticket nào lặp lại.',['Phân tích nhóm ticket, thời gian xử lý và lỗi hiện tại.','Chọn một nhóm task có dữ liệu/đáp án kiểm được, so search hoặc FAQ với LLM.','Đặt gate về giải quyết đúng và escalation, đo cả thời gian review.'],'Quyết định dùng AI dựa trên dữ liệu task thật, không chỉ cảm nhận của người xem demo.'],
    ['Không dùng “tỷ lệ trả lời” thay “tỷ lệ giải quyết đúng”.','Đừng chọn công nghệ trước rồi tìm vấn đề để khớp nó.'],
    [['Baseline để làm gì?','Để biết giải pháp mới cải thiện gì so cách hiện tại hoặc cách đơn giản, với cùng dữ liệu và điều kiện.'],['Khi nào nên no-go?','Khi thiếu dữ liệu/quyền, không đánh giá được, cost of error quá cao hoặc lợi ích không vượt baseline/chi phí.'],['Một problem statement tốt có gì?','User, công việc/pain, outcome, phạm vi, dữ liệu, baseline, metric và constraints rõ.']]);

  O(3,
    'Agent tạo thành vòng quan sát và hành động theo mục tiêu. Khi hành động do model đề xuất, code vẫn cần kiểm quyền, budget và kết quả.',
    'Vẽ được vòng ReAct, biết observation ảnh hưởng bước sau và đặt được điều kiện dừng.',
    [['Nhận mục tiêu','Xác định outcome và những công cụ được phép dùng.','Task cùng giới hạn'],['Chọn hành động','Model đề xuất trả lời hoặc tool call dựa trên context hiện có.','Action dự kiến'],['Kiểm và thực thi','Ứng dụng validate schema/quyền, thực thi rồi ghi trạng thái.','Kết quả thật của tool'],['Quan sát và cập nhật','Observation (kết quả quan sát từ môi trường) được đưa về context để điều chỉnh bước tiếp.','Context mới'],['Dừng và verify','Dừng khi đạt mục tiêu, hết budget hoặc cần chuyển người; kiểm kết quả ở hệ đích.','Outcome có bằng chứng']],
    [['Ba kiểu hệ thống','Chatbot, workflow và agent','Chatbot chủ yếu tạo phản hồi; workflow có luồng code định trước; agent có thể chọn bước theo quan sát. Một sản phẩm có thể kết hợp cả ba.'],['Agentic fit','Đủ lý do cho vòng tự quyết','Agentic fit (mức phù hợp dùng agent) cao hơn khi task có đường đi khó xác định trước, tool rõ và outcome kiểm được.'],['ReAct','Suy luận đi cùng phản hồi','ReAct kết hợp reasoning (suy luận), action (hành động) và observation. Thiếu observation thì model không biết kết quả thực của bước vừa làm.'],['Agent loop','Loop cần bộ điều khiển','Giới hạn số bước, deadline, điều kiện hoàn tất và cơ chế escalation để tránh lặp, tăng chi phí hoặc chạy vô hạn.'],['Debug & so sánh','Trace thay vì đoán prompt','Trace (dấu vết chuỗi xử lý) cho thấy tool nào gọi, dữ liệu gì trả về và quyết định nào sai; so agent với workflow/baseline theo task thật.']],
    ['Dùng output schema, error categories và tool call IDs để debug.','Tách việc đọc dữ liệu khỏi hành động có side effect; yêu cầu gate theo mức rủi ro.'],
    ['Các kiến trúc reflection/search nâng cao ở bài 16 sau khi loop cơ bản đã kiểm soát được.'],
    ['Agent nói đã kiểm đơn hàng nhưng trace không có tool call tra đơn.',['Xác định yêu cầu cần dữ liệu hệ thống nào.','Buộc xác nhận qua tool observation có schema và quyền.','Chặn lời báo hoàn tất khi thiếu evidence, thêm case tool lỗi và trả rỗng.'],'Trả lời khớp trạng thái đơn thật; thiếu quyền/dữ liệu thì nêu giới hạn hoặc chuyển người.'],
    ['Không gọi một prompt dài là agent chỉ vì có nhiều bước được mô tả.','Tool call thành công chưa đủ chứng minh toàn bộ task hoàn tất.'],
    [['Observation bị bỏ khỏi vòng lặp thì sao?','Model không có phản hồi thực để điều chỉnh và có thể suy đoán kết quả tool.'],['Những điều kiện dừng nào cần có?','Đạt outcome được verify, hết step/time/cost budget, lỗi không phục hồi hoặc cần dữ liệu/quyết định từ người.'],['Khi nào workflow phù hợp hơn agent?','Khi các bước ổn định, ít nhánh mơ hồ, dễ mô tả bằng code và cần kiểm soát rõ.']]);

  O(4,
    'Prompt truyền mục tiêu và ngữ cảnh; tool contract biến một phần quyết định thành dữ liệu có cấu trúc. Code chịu trách nhiệm thực thi an toàn và phản hồi kết quả.',
    'Thiết kế prompt cùng tool schema, validation và vòng xử lý lỗi có thể kiểm thử.',
    [['Định nghĩa nhiệm vụ','Nêu mục tiêu, dữ liệu, constraints, tiêu chí và output cần có.','Prompt rõ'],['Cấp context','Chọn thông tin liên quan, đánh dấu dữ liệu không tin cậy và giữ ưu tiên instruction.','Context đủ và đúng vai'],['Mô tả tool','Viết tên, mô tả, input/output schema và điều kiện lỗi theo nghiệp vụ.','Tool contract'],['Validate rồi execute','Kiểm JSON/schema, quyền và giá trị nghiệp vụ trước side effect.','Thao tác hợp lệ'],['Trả observation và test','Gắn kết quả đúng call, cho model xử lý trong budget; test happy path và failure path.','Vòng tool có bằng chứng']],
    [['Prompt structure','Mục tiêu, dữ liệu và tiêu chí','Prompt structure (cấu trúc chỉ dẫn) cần phân biệt việc phải làm, context, ràng buộc và format; thêm ví dụ khi chúng làm rõ tiêu chí.'],['System & context','Ưu tiên chỉ dẫn và độ tin cậy','System instruction và tài liệu/tool output có vai trò khác nhau. Nội dung retrieved không tự có quyền thay mục tiêu hoặc policy.'],['Tool contract','Schema là ranh giới dữ liệu','Tool schema (mô tả dữ liệu lời gọi) giúp model chọn tham số; valid JSON không đồng nghĩa giá trị nghiệp vụ đúng hoặc người gọi có quyền.'],['Tool execution','App thực thi và xử lý lỗi','Tool execution (thực thi công cụ) cần validation, auth, timeout và kết quả có trạng thái; trả lỗi hữu ích mà không lộ secret.'],['Reliability & security','Prompt không thay runtime controls','Retry chọn lọc, idempotency, giới hạn call và approval cho action nhạy cảm phải do hệ thống cưỡng chế.']],
    ['Dùng few-shot (một số ví dụ mẫu) có đại diện và kiểm regression khi sửa prompt.','Phân biệt orchestration (điều phối luồng) bằng code với việc model tự chọn hành động.'],
    ['Tối ưu prompt caching và middleware khi đo thấy cost/context là bottleneck.'],
    ['Tool chuyển tiền nhận JSON đúng schema nhưng sai tài khoản thụ hưởng.',['Kiểm danh tính, quyền và rule nghiệp vụ ngoài schema.','Cho người duyệt đúng payload nếu policy yêu cầu.','Ghi observation từ hệ đích và chặn lặp tác động khi retry.'],'JSON hợp lệ chưa đủ; đúng đối tượng, quyền và external state mới đạt.'],
    ['Không đặt secret vào prompt hoặc log toàn bộ tool payload một cách mặc định.','Không thưởng prompt chỉ vì đáp án trông đúng format khi nội dung sai.'],
    [['Schema validation và business validation khác nhau thế nào?','Schema kiểm kiểu/cấu trúc; business validation kiểm giá trị và quan hệ có hợp nghiệp vụ hiện tại không.'],['Vì sao model không nên tự xác nhận tool thành công?','Nó cần observation thực; lời sinh ra có thể suy đoán hoặc nhầm kết quả của call khác.'],['Sửa prompt xong kiểm gì?','Cùng bộ case về chất lượng, format, tool chọn/tham số, lỗi và an toàn; so với baseline trước sửa.']]);

  O(5,
    'Sản phẩm AI cần chuyển giá trị mong muốn thành hành vi đo được và ranh giới rủi ro. PRD phải mô tả cả khi AI không chắc, thất bại hoặc cần người xử lý.',
    'Viết yêu cầu AI có acceptance criteria, metric chất lượng/giá trị và phương án fallback.',
    [['Hiểu user','Tìm công việc, pain point và tác động lên các nhóm liên quan.','Nhu cầu được xác nhận'],['Chốt outcome','Xác định thay đổi nào tạo giá trị và điều gì nằm ngoài phạm vi.','Mục tiêu sản phẩm'],['Viết yêu cầu','Định nghĩa hành vi, dữ liệu, constraints, uncertainty và luồng lỗi.','PRD có ranh giới'],['Đặt tiêu chí chấp nhận','Chọn metrics và case pass/fail; có chỉ số bảo vệ rủi ro.','Acceptance criteria'],['Validate và cập nhật','Dùng prototype/task test để kiểm giả thuyết; cập nhật theo evidence.','Quyết định sản phẩm']],
    [['Product value','Giá trị gắn công việc của user','Product value (giá trị sản phẩm) cần kết quả như giảm thời gian xử lý đúng hoặc tăng khả năng hoàn thành việc, không chỉ tăng số lượt chat.'],['User research','Tìm evidence thay cho giả định','User research (nghiên cứu người dùng) cần quan sát bối cảnh và hành vi; lời nói thích demo chưa bằng việc dùng để hoàn thành task.'],['Requirements','Yêu cầu gồm cả luồng không chắc','Functional requirements (yêu cầu chức năng) và non-functional requirements (yêu cầu chất lượng vận hành) cần thêm fallback, escalation, privacy và quyền.'],['PRD & metrics','Có tiêu chí kiểm lại được','PRD (tài liệu yêu cầu sản phẩm) phải nối user need → hành vi → metric → acceptance criteria, với tập case hoặc cách đo rõ.'],['Responsible AI','Rủi ro là phần của thiết kế','Responsible AI (AI có trách nhiệm) gồm fairness, privacy, minh bạch và trách nhiệm xử lý theo tác động thực; cần owner và biện pháp kiểm.']],
    ['Phân loại assumption, constraint và requirement để tránh chốt nhầm điều chưa được kiểm.','Ưu tiên theo impact, effort, uncertainty và mức rủi ro.'],
    ['Các phương pháp discovery/quản trị chuyên sâu khi quy mô đội và số stakeholder tăng.'],
    ['PRD chỉ ghi “chatbot trả lời thông minh, nhanh và chính xác”.',['Chốt nhóm user/task và dữ liệu cần được phép truy cập.','Viết case đạt/không đạt, metric và mức lỗi cho phép theo risk.','Bổ sung từ chối khi thiếu evidence và handoff có owner.'],'Một reviewer có thể chạy test để quyết định pass/fail mà không cần đoán ý tác giả.'],
    ['Không dùng “AI sẽ hiểu” để thay một requirement còn thiếu.','Không coi một metric trung bình là mô tả đầy đủ tác động lên mọi nhóm user.'],
    [['Acceptance criteria tốt khác khẩu hiệu thế nào?','Có hành vi, điều kiện, phép kiểm và tiêu chí pass/fail cụ thể.'],['Vì sao PRD AI cần fallback?','Model và nguồn có thể không chắc hoặc lỗi; sản phẩm vẫn cần đường xử lý đúng quyền và có trách nhiệm.'],['Metric sản phẩm và metric model khác gì?','Metric model đo một khía cạnh kỹ thuật; metric sản phẩm đo tác động đến công việc hoặc giá trị user, cần liên hệ nhưng không đồng nhất.']]);

  O(6,
    'Quản lý dự án AI là giảm bất định bằng thí nghiệm nhỏ trước khi cam kết lớn. Mỗi vòng cần giả thuyết, bằng chứng và quyết định tiếp theo.',
    'Lập một thí nghiệm có baseline và DoD, phân biệt PoC/MVE/MVP và báo ROI có giả định.',
    [['Chọn giả thuyết','Tìm điều chưa biết có thể làm dự án thất bại.','Rủi ro ưu tiên'],['Chọn phép thử nhỏ','Dùng MVE/PoC phù hợp để học nhanh điều đó với baseline.','Thiết kế thí nghiệm'],['Thực hiện và đo','Giữ dữ liệu, cấu hình và tiêu chí đủ rõ để so sánh.','Kết quả có thể đọc lại'],['Quyết định phạm vi','Go, pivot hoặc stop theo bằng chứng; lập MVP khi giá trị cốt lõi có cơ sở.','Backlog cập nhật'],['Giao tiếp và vận hành','Báo giá trị, tổng chi phí, giới hạn và owner; chốt điều kiện hoàn tất.','Kế hoạch có trách nhiệm']],
    [['MVE, MVP, PoC','Ba sản phẩm của ba câu hỏi','PoC (thử tính khả thi) hỏi làm được không; MVE (thí nghiệm tối thiểu) kiểm giả thuyết; MVP (sản phẩm khả dụng tối thiểu) cung cấp giá trị cốt lõi để học từ sử dụng.'],['Experiment','Một thay đổi cần phép so','Experiment (thí nghiệm) cần giả thuyết, baseline, dữ liệu và tiêu chí trước khi xem điểm; thay nhiều thứ cùng lúc làm yếu kết luận nguyên nhân.'],['Agile & DoD','Hoàn tất phải có bằng chứng','DoD — Definition of Done (định nghĩa hoàn tất) cần artifact, kiểm tra chức năng/chất lượng và ranh giới vận hành, không chỉ “API đã chạy”.'],['ROI','Giá trị trừ toàn bộ chi phí','ROI (lợi tức đầu tư) cần tính API, hạ tầng, dữ liệu, nhân lực review/vận hành và chi phí lỗi; các giả định phải được nêu rõ.'],['Stakeholder','Nói rõ điều đã và chưa chứng minh','Stakeholder (bên liên quan) cần biết outcome, risk, evidence và quyết định cần đưa ra; không biến demo thành lời hứa production.']],
    ['Chia milestone theo outcome/learning, có dependency và owner.','Tách chỉ số dẫn dắt, kết quả cuối và giới hạn dữ liệu khi báo cáo.'],
    ['Thiết kế thí nghiệm thống kê nâng cao sau khi bộ đo cơ bản đáng tin.'],
    ['Đội muốn xây đủ hệ thống trước khi biết dữ liệu có giúp trả lời đúng không.',['Chọn giả thuyết giá trị cốt lõi và tập task nhỏ có nhãn.','Chạy MVE với baseline, ghi effort review và chi phí.','Chỉ mở rộng MVP khi gate đạt hoặc có lý do pivot rõ.'],'Quyết định đầu tư dựa trên phép đo và giả định được công khai, không dựa công sức đã bỏ ra.'],
    ['Tránh sunk cost: đã làm nhiều không phải bằng chứng nên tiếp tục.','Một PoC chạy được không có nghĩa dữ liệu, UX và vận hành đều sẵn sàng.'],
    [['Khi nào dùng MVE?','Khi cần kiểm một giả thuyết quan trọng bằng phép thử nhỏ nhất đủ đưa ra quyết định.'],['DoD cho feature AI nên thêm gì?','Eval, failure/fallback, quyền dữ liệu, telemetry và artifact tái hiện, tùy risk và phạm vi triển khai.'],['Vì sao tính token cost chưa đủ ROI?','Còn chi phí hạ tầng, dữ liệu, review, vận hành, tích hợp và hậu quả của lỗi.']]);

  O(7,
    'Retrieval tốt bắt đầu từ dữ liệu đọc đúng, chia đúng và có metadata. Vector similarity giúp tìm gần nghĩa nhưng không tự xác nhận đúng sự thật hoặc quyền truy cập.',
    'Giải thích đường tài liệu → chunk → embedding → index → kết quả tìm và kiểm được lỗi ở từng tầng.',
    [['Chọn dữ liệu','Kiểm quyền dùng, chất lượng, cấu trúc, độ mới và nguồn gốc.','Corpus có phạm vi'],['Parse và chunk','Đọc đúng text/bảng và chia đoạn giữ đủ ngữ nghĩa, ID cùng nguồn.','Chunk kiểm được'],['Embed và index','Embedding biến dữ liệu thành vector; index hỗ trợ tìm kiếm trong giới hạn tài nguyên.','Vector gắn metadata'],['Tìm và lọc','Dùng query vector/từ khóa, filter quyền và metadata; rerank khi cần.','Tập kết quả phù hợp'],['Đánh giá và cập nhật','Đo relevance/recall, hiệu năng và rò quyền; đồng bộ thay đổi/xóa.','Search có evidence']],
    [['Parsing','Đọc đúng trước khi tìm','Parsing (trích nội dung có cấu trúc) phải giữ bảng, thứ tự và phần liên quan; đoạn text hỏng không được sửa bằng tăng top-k.'],['Chunking','Độ lớn đoạn là đánh đổi','Chunking cần đủ context nhưng tránh nhiều nội dung thừa; chọn theo cấu trúc và đo theo query thật, không có một chunk size tốt cho mọi dữ liệu.'],['Embedding','Vector biểu diễn tín hiệu tương tự','Embedding (biểu diễn dữ liệu bằng vector) giúp so gần nghĩa; model, chiều vector và cách xử lý input phải nhất quán giữa query/index.'],['Search & ANN','Nhanh hơn có thể giảm recall','ANN — approximate nearest neighbor (tìm láng giềng gần đúng) đánh đổi recall, latency và memory; phải đo trên workload và cấu hình index.'],['Evaluation & security','Metadata phục vụ cả relevance và quyền','Gắn source, version, tenant/quyền để lọc và truy nguồn; không để similarity cao trở thành quyền xem dữ liệu.']],
    ['Hiểu hybrid retrieval kết hợp từ khóa với dense vector và vai trò rerank.','Dùng dữ liệu truy vấn có nhãn để chọn tham số thay vì chỉ xem vài ví dụ thuận lợi.'],
    ['Các thuật toán index, quantization và tối ưu dimension sau khi xác định bottleneck.'],
    ['Search không tìm được một hàng trong bảng giá và trả chunk của tenant khác.',['Kiểm bảng đã parse đúng và chunk có giữ tên cột.','Kiểm metadata/filter quyền trước khi rank hoặc trả kết quả.','Chạy eval relevance và cross-tenant cases.'],'Tìm đúng hàng với nguồn/version đúng, không lộ dữ liệu khác tenant.'],
    ['Similarity không đồng nghĩa factual correctness.','Không index dữ liệu thiếu quyền rồi chỉ trông chờ model tự giấu.'],
    [['Vì sao cần metadata bên cạnh vector?','Để lọc theo quyền/phạm vi, biết nguồn/version và quản lý cập nhật, xóa, truy vết.'],['Tăng chunk size có luôn tốt không?','Không; giữ nhiều context hơn nhưng có thể làm loãng tín hiệu, tăng cost và đưa nhiều nội dung không liên quan.'],['ANN cần đo đánh đổi gì?','Recall của kết quả, latency, memory, build/update cost và điều kiện dữ liệu/tải.']]);

  O(8,
    'RAG cấp bằng chứng từ dữ liệu ngoài vào quá trình tạo câu trả lời. Retrieval lấy được tài liệu chưa đủ: model còn phải dùng đúng bằng chứng và biết khi thiếu.',
    'Vẽ được hai luồng indexing/query và kiểm một câu trả lời có citation ở mức claim.',
    [['Indexing · offline','Parse, chunk, thêm metadata, embed và lưu index; kiểm version/quyền.','Kho có thể tìm'],['Hiểu query · online','Xác định intent và biến đổi query nếu cách diễn đạt gây khó retrieval.','Query phù hợp'],['Retrieve rồi rerank','Lấy ứng viên, lọc quyền và chọn evidence trong budget.','Context liên quan'],['Generate có grounding','Grounding (gắn câu trả lời với bằng chứng) yêu cầu claim dựa nguồn; thiếu evidence thì nêu giới hạn.','Answer kèm nguồn'],['Eval và feedback','Đo retrieval, answer và outcome; đưa lỗi về đúng tầng.','Vòng cải tiến RAG']],
    [['RAG architecture','Hai luồng riêng nhưng liên quan','RAG — retrieval-augmented generation (sinh câu trả lời có truy xuất bổ sung) gồm chuẩn bị index và truy vấn lúc sử dụng; lỗi offline có thể xuất hiện thành lỗi answer.'],['Ingestion & chunking','Evidence phải còn nguyên nghĩa','Ingestion (nạp dữ liệu) cần giữ nguồn, cấu trúc, điều kiện và ngoại lệ; chunk tốt cho một loại query có thể kém cho loại khác.'],['Query transform','Sửa query phải giữ intent','Query transform (biến đổi truy vấn) có thể làm rõ hoặc mở rộng tìm kiếm; phải tránh đổi câu hỏi thành điều khác.'],['Grounding & UX','Citation phải hỗ trợ claim','Một URL hợp lệ không đủ. Kiểm đoạn nguồn có hỗ trợ đúng chủ thể, thời điểm và điều kiện của claim không; nói rõ phần chưa biết.'],['RAG evaluation','Đủ nguồn và dùng đúng nguồn','Đo độ phủ/chất lượng retrieval riêng với faithfulness, relevance và correctness của answer; không lấy một điểm tổng để định vị mọi lỗi.']],
    ['So prompt-only, naive RAG và bản nâng cấp trên cùng bộ query.','Thiết kế UX cho thiếu dữ liệu, nguồn mâu thuẫn và độ mới.'],
    ['Các kỹ thuật chunking/retriever nâng cao trong bài 18 sau khi pipeline cơ bản có eval.'],
    ['Bot trích đúng tài liệu hoàn tiền nhưng bỏ qua ngoại lệ của sản phẩm đã dùng.',['Kiểm ngoại lệ có nằm trong chunk/context hay không.','Nếu có context đúng, kiểm generation và claim support; nếu thiếu, sửa retrieval/ingestion.','Thêm case ngoại lệ vào regression và hiển thị điều kiện trong answer.'],'Trả đủ điều kiện với nguồn hỗ trợ, hoặc nêu thiếu bằng chứng thay vì suy đoán.'],
    ['RAG không mặc định xóa hallucination.','Có nhiều citation không có nghĩa các claim đều được nguồn hỗ trợ.'],
    [['Khi nào lỗi thuộc generation?','Khi context đã có đúng bằng chứng cần thiết nhưng answer dùng sai, bỏ sót hoặc thêm claim không được hỗ trợ.'],['RAG có cần train lại model để cập nhật tài liệu không?','Không nhất thiết; có thể cập nhật corpus/index, nhưng phải xử lý version, xóa và cache đúng.'],['Context đúng một phần thì nên làm gì?','Chỉ trả phần được hỗ trợ, nêu rõ thiếu thông tin hoặc tìm/chuyển người theo policy.']]);

  O(9,
    'Phối hợp nhiều agent và công cụ cần contract, state và quyền rõ ràng. MCP chuẩn hóa kết nối tool; A2A phục vụ phối hợp giữa agent, không tự giải bài toán điều phối.',
    'Phân biệt agent–tool với agent–agent và vẽ được dependency, state cùng điểm kiểm quyền.',
    [['Phân rã theo nhiệm vụ','Xác định phần nào cần context riêng, phần nào chạy tuần tự hoặc song song.','Dependency map'],['Đặt vai và contract','Mỗi agent/tool có đầu vào, output, quyền và tiêu chí hoàn tất.','Ranh giới rõ'],['Chọn kết nối','Dùng MCP cho capability công cụ và cơ chế agent–agent theo nhu cầu phối hợp.','Giao tiếp phù hợp'],['Điều phối state','Route, handoff, join và xử lý lỗi theo ownership cùng budget.','State nhất quán'],['Trace và so baseline','Kiểm chất lượng outcome, cost, latency và quyền qua cả chuỗi.','Bằng chứng lợi ích']],
    [['Agent fit & patterns','Mẫu phối hợp phải khớp dependency','Router, supervisor, pipeline và parallel là cách tổ chức việc; task đơn giản có thể không cần multi-agent (hệ nhiều agent).'],['Coordination','Handoff cần dữ liệu và trạng thái','Coordination (phối hợp) cần owner, schema, điều kiện chuyển bước và xử lý partial result; vai trò đặt tên hay không thay contract.'],['MCP','Agent dùng tool qua chuẩn kết nối','MCP (giao thức ngữ cảnh cho model) hỗ trợ khám phá/sử dụng capability từ server; host vẫn kiểm quyền và thực thi theo policy.'],['A2A','Giao tiếp giữa các agent','A2A — agent-to-agent (agent giao tiếp với agent) hướng tới trao đổi nhiệm vụ/capability và trạng thái; không đồng nghĩa chia sẻ mọi memory hay quyền.'],['Observability & safety','Toàn chuỗi cần đo và giới hạn','Giữ correlation ID, tool/agent trace, token/cost budget và kiểm quyền; lỗi ở một worker có thể lan qua bước tổng hợp.']],
    ['Hiểu shared state và reducer trong workflow có nhánh đồng thời.','Task dài cần brief, plan và context management để tránh drift.'],
    ['Các topology nâng cao và harness tự cải tiến ở bài 20 sau khi có baseline đáng tin.'],
    ['Ba agent cùng sửa báo cáo, kết quả cuối bị mất nội dung và tốn hơn single-agent.',['Xác định ai sở hữu artifact và phần nào có thể tách độc lập.','Đặt output contract và một owner merge.','So cùng task với single-agent, đo quality/cost/latency.'],'Không ghi đè ngoài owner; multi-agent chỉ được giữ nếu lợi ích được chứng minh theo yêu cầu.'],
    ['Một protocol không tự cấp quyền hoặc đảm bảo agent nói sự thật.','Thêm agent thường tăng overhead trước khi tạo giá trị.'],
    [['MCP và A2A khác trọng tâm ở đâu?','MCP thường phục vụ kết nối capability/tool/data cho host AI; A2A tập trung giao tiếp và nhiệm vụ giữa agent.'],['Tại sao một owner ghi artifact có ích?','Giảm conflict và mất dữ liệu; worker có thể đề xuất phần riêng để owner kiểm/merge.'],['Cần đo gì ngoài accuracy?','Latency, chi phí, số call, lỗi điều phối, khả năng recovery và vi phạm quyền trong trajectory.']]);

  O(10,
    'Data pipeline đưa dữ liệu từ nguồn tới nơi phục vụ với chất lượng và độ mới kiểm được. Khi dữ liệu sai, lineage giúp tìm tác động và sửa đúng phần.',
    'Theo được một bản ghi qua ingestion, transform, storage, serving và thiết kế quality/freshness gates.',
    [['Ingest','Lấy batch hoặc stream từ nguồn với watermark/ID và policy xử lý lỗi.','Dữ liệu thô có nguồn'],['Validate','Kiểm schema, completeness, giá trị và quyền trước khi phát tán lỗi.','Dữ liệu đạt contract'],['Transform và lưu','Làm sạch/chuyển đổi có version, xử lý trùng và chọn storage theo cách đọc.','Dataset có thể phục vụ'],['Serve và quan sát','Cấp dữ liệu đúng độ mới, theo dõi freshness, volume và lỗi chất lượng.','Dữ liệu dùng được'],['Điều tra và phục hồi','Dùng lineage để xác định nguồn lỗi, phạm vi ảnh hưởng và backfill/replay an toàn.','Pipeline phục hồi có kiểm']],
    [['ETL/ELT & ingestion','Thứ tự transform và load có đánh đổi','ETL (trích–biến đổi–nạp) và ELT (trích–nạp–biến đổi) khác nơi/thời điểm xử lý; chọn theo dữ liệu, governance và hạ tầng.'],['Quality & contracts','Schema đúng chưa đủ dữ liệu tốt','Data contract (giao kèo dữ liệu) nêu cấu trúc, ý nghĩa, chất lượng, độ mới và owner; cần kiểm cả giá trị và phân bố.'],['Data observability','Quan sát dữ liệu theo nhiều chiều','Data observability (khả năng theo dõi sức khỏe dữ liệu) xét freshness, volume, schema, distribution và lineage; pipeline xanh vẫn có thể nạp dữ liệu cũ.'],['Lineage & incident','Biết dữ liệu đi từ đâu tới đâu','Lineage (dòng dõi dữ liệu) nối nguồn, transform và consumer để điều tra root cause và xác định ai bị ảnh hưởng.'],['Orchestration & cost','Lịch chạy và replay có contract','Orchestration cần dependency, retry, idempotency, watermark và quản lý tài nguyên; replay không được tạo trùng hay bỏ sót.']],
    ['Phân biệt batch/stream và event time/processing time theo yêu cầu độ trễ.','Có quarantine cho dữ liệu lỗi và policy backfill khi nguồn sửa.'],
    ['Tối ưu storage/partitioning và distributed streaming khi quy mô yêu cầu.'],
    ['Dashboard RAG báo pipeline thành công nhưng index vẫn dùng dữ liệu hôm qua.',['Kiểm freshness theo thời điểm dữ liệu, watermark và bước ingest/index.','Dùng lineage để tìm chỗ dữ liệu bị kẹt.','Backfill có ID/version và kiểm quality trước chuyển alias.'],'Query dùng đúng version hiện hành; dữ liệu replay không trùng và consumer được thông báo phạm vi ảnh hưởng.'],
    ['Không dùng job exit code làm bằng chứng dữ liệu đúng và mới.','Không replay toàn bộ trước khi biết contract trùng lặp và side effect.'],
    [['Freshness khác latency job thế nào?','Freshness đo độ mới của dữ liệu so thời điểm cần dùng; một job chạy nhanh vẫn có thể đọc dữ liệu cũ.'],['Lineage giúp incident thế nào?','Cho biết nguồn/transform gây lỗi và downstream chịu ảnh hưởng để khoanh vùng sửa và thông báo.'],['Quality gate fail nên làm gì?','Chặn hoặc quarantine theo policy, giữ bằng chứng/owner và tránh phát tán dữ liệu sai tới consumer.']]);

  O(11,
    'An toàn AI cần nhiều lớp kiểm soát theo tác động: dữ liệu vào, nội dung truy xuất, quyền hành động và kết quả ra. Con người tham gia khi risk hoặc uncertainty vượt phạm vi tự động hóa.',
    'Vẽ được threat model và đặt guardrail/HITL ở trước tác động cần bảo vệ.',
    [['Xác định risk','Xác định tài sản, actor, đường tấn công và cost of error.','Threat model'],['Phân lớp kiểm','Kiểm input, dữ liệu/tool output, execution và output theo từng rủi ro.','Control map'],['Giới hạn action','Auth, least privilege và sandbox phù hợp; approval trước action nhạy cảm.','Quyền tối thiểu'],['Handoff cho người','Trình evidence, payload và lựa chọn rõ; có reject/timeout/escalation.','Quyết định có trách nhiệm'],['Red team và đo','Test attack lẫn request hợp lệ; đưa lỗi thành regression.','Safety evidence']],
    [['Attack vectors','Dữ liệu cũng có thể chứa chỉ thị giả','Prompt injection (chèn chỉ thị nhằm đổi hành vi) có thể đến trực tiếp từ user hoặc gián tiếp qua tài liệu/tool; không nâng nguồn dữ liệu thành authority.'],['Guardrail layers','Mỗi boundary chặn một loại lỗi','Guardrail (lớp kiểm soát) gồm schema, policy, detector và runtime enforcement; output filter không thay auth của tool.'],['Tool safety','Quyền phải được cưỡng chế','Least privilege (quyền tối thiểu) giới hạn tool/phạm vi dữ liệu; validate cả danh tính, tham số và nghiệp vụ trước side effect.'],['HITL & escalation','Người can thiệp đúng lúc','HITL (con người tham gia trực tiếp) cần đủ context để approve/edit/reject đúng action; confidence cao không vượt hard rule.'],['Red teaming','Tấn công thử và kiểm usefulness','Red teaming (kiểm thử đối kháng) tìm đường vượt rào trong scope; đo cả unsafe pass và over-refusal (từ chối quá mức).']],
    ['Privacy, fairness và trách nhiệm giải trình cần owner và phép kiểm theo use case.','Theo dõi nhiều lượt để phát hiện memory/session poisoning, không chỉ một prompt đơn.'],
    ['Framework guardrail chuyên biệt sau khi đã định nghĩa rõ policy, boundary và eval.'],
    ['Một chunk RAG ra lệnh gửi dữ liệu khách hàng ra ngoài, bot vẫn trả lời cuối rất lịch sự.',['Giữ chunk ở vai trò dữ liệu, không cho đổi policy.','Chặn quyền đọc/gửi ngoài scope tại runtime trước execution.','Test nhiều lượt và kiểm mọi external effect trong trace.'],'Không có dữ liệu bị gửi trái quyền; request hợp lệ vẫn làm được hoặc được handoff rõ.'],
    ['Không dùng prompt “hãy an toàn” thay quyền và validation.','Một lần từ chối tấn công không chứng minh chống được mọi biến thể.'],
    [['Vì sao chỉ lọc output là thiếu?','Tool có thể đã tạo side effect trái quyền trước khi output cuối bị kiểm.'],['Khi nào chuyển người?','Theo risk, policy cứng, dữ liệu thiếu/không chắc hoặc hành động ngoài phạm vi tự quyết; không chỉ dựa độ tự tin câu chữ.'],['Safety eval cần mẫu hợp lệ để làm gì?','Để phát hiện over-blocking và đảm bảo control không phá nhiệm vụ an toàn cần phục vụ.']]);

  O(12,
    'Deploy đưa app vào môi trường có cấu hình, network, state và tải khác local. Một container khởi động được chỉ là một lớp bằng chứng; còn phải kiểm task và dữ liệu thực.',
    'Theo được đường code → image → runtime → request → state và chốt một release có eval/rollback.',
    [['Đóng gói','Pin dependency, tạo image tái lập và tách config/secret khỏi code.','Artifact có version'],['Cấu hình runtime','Đặt port, bind, network, tài nguyên, identity và kết nối dịch vụ.','Service khởi động đúng'],['Quản lý state','Đưa checkpoint/store cần bền ra backend phù hợp; xét nhiều instance và restart.','State không mất ngoài ý muốn'],['Kiểm qua endpoint thật','Test auth, timeout, tool/provider và outcome ở môi trường đích.','E2E evidence'],['Phát hành có gate','CI/CD kiểm build, tests, eval và rollout/rollback có owner.','Release kiểm soát được']],
    [['Docker & config','Image và runtime config khác nhau','Docker image đóng gói app/dependencies; secrets và cấu hình theo môi trường cần được cấp an toàn lúc chạy, không ghi cứng vào image.'],['Stateful agent','Process không phải nơi lưu bền mặc định','Stateful agent (agent có trạng thái) cần checkpoint/store và định danh thread; nhiều instance dùng state in-memory riêng có thể cho hành vi khác nhau.'],['Hosting & MCP','Có listener chưa chứng minh đúng app','Kiểm process, endpoint, transport và môi trường chạy; healthcheck chỉ chứng minh điều nó thực sự kiểm.'],['Security & scale','Scale làm rõ ranh giới tài nguyên','Auth, rate limit, timeout, concurrency và quyền egress/data phải hợp deployment; tăng replica không tự giải shared state hay provider quota.'],['CI/CD & model serving','Gate cả code lẫn hành vi model','CI/CD (tích hợp và phát hành liên tục) cần test cùng eval theo risk; model serving (phục vụ model) cần artifact/config tương thích và rollback.']],
    ['Phân biệt liveness, readiness và business probe khi thiết kế healthchecks.','Log có correlation ID và version để liên hệ lỗi với release/config.'],
    ['Tối ưu GPU serving, autoscaling và distributed state khi workload thật cần.'],
    ['Deploy báo thành công nhưng agent mất thread khi restart và tool không gọi được API.',['Xác minh endpoint đúng service/config và đọc log theo request ID.','Đưa state cần bền vào backend phù hợp, kiểm credential/network không lộ secret.','Chạy restart/reload và E2E action tests trước chuyển traffic.'],'Thread khôi phục đúng và tool hoàn thành business case ở môi trường đích; healthcheck không thay phép kiểm này.'],
    ['Local pass không chứng minh deploy đã dùng đúng DB/provider/config.','Không dùng image build hoặc HTTP 200 làm bằng chứng toàn bộ feature đã chạy.'],
    [['Vì sao không nên nhúng secret vào image?','Image có thể được chia sẻ/lưu nhiều nơi; secret cần cấp theo môi trường, quyền tối thiểu và có thể xoay vòng.'],['Scale-out ảnh hưởng state thế nào?','Request có thể sang instance khác; state in-memory riêng không tự đồng bộ hoặc bền qua restart.'],['Release cần bằng chứng gì ngoài startup?','Auth, dữ liệu/config đúng, provider/tool integration, E2E outcome, eval gates, monitoring và đường rollback theo phạm vi.']]);

  O(13,
    'Observability giúp trả lời request nào sai, sai ở đâu và ảnh hưởng ai. Metrics cho xu hướng, logs cho sự kiện và traces nối các bước; chúng phải dẫn tới quyết định vận hành.',
    'Lần một incident từ tín hiệu trên dashboard tới span/tool/source gây lỗi và kiểm lại sau khi sửa.',
    [['Định nghĩa tín hiệu','Chọn outcome, latency, cost và failure modes gắn nhu cầu vận hành.','SLIs hữu ích'],['Instrument','Ghi logs có cấu trúc và spans với request/trace IDs, version và trạng thái.','Telemetry truy vết được'],['Tổng hợp','Dashboard theo cohort/task/provider để tránh điểm trung bình che lỗi.','Bức tranh hệ thống'],['Alert và điều tra','Cảnh báo có ngưỡng, owner/runbook; đi từ triệu chứng qua trace tới bằng chứng nguyên nhân.','Giả thuyết có dữ kiện'],['Sửa và kiểm lại','Kiểm metric phục hồi, outcome thật và regression; đưa case vào eval.','Vòng vận hành đóng']],
    [['Pillars','Ba loại bằng chứng bổ sung nhau','Metrics (số đo tổng hợp) cho biết mức độ/tần suất; logs (nhật ký sự kiện) mô tả việc xảy ra; traces (dấu vết request qua các bước) nối quan hệ thời gian và phụ thuộc.'],['AI metrics','Đo cả chất lượng lẫn tài nguyên','Task success, grounding, token/cost, time-to-first-token và end-to-end latency đo các khía cạnh khác nhau; HTTP success chưa bằng task success.'],['Structured logs','Sự kiện đọc và lọc được','Structured logging (ghi log có cấu trúc) dùng trường như request ID, component, version, status và duration; tránh secret/PII không cần thiết.'],['Tracing','Một request đi qua những gì?','Span (đoạn xử lý trong trace) nên chỉ ra retrieval/model/tool và kết quả tương ứng; trace minh họa không tự là bằng chứng live provider.'],['Dashboard & alerts','Tín hiệu phải dẫn tới hành động','Alert cần điều kiện, owner và runbook; tách theo task/cohort để phát hiện silent quality degradation.']],
    ['Feedback user cần liên kết với request/version và có xử lý privacy.','Biết sampling, cardinality và retention ảnh hưởng chi phí lẫn khả năng điều tra.'],
    ['Distributed tracing nâng cao và tối ưu telemetry khi quy mô làm xuất hiện bottleneck cụ thể.'],
    ['p95 latency tăng nhưng tỷ lệ HTTP lỗi không đổi.',['Tách metric theo provider, task và release.','Đọc trace request chậm để biết retrieval, model hay tool tăng thời gian.','So quality/cost và kiểm ngoại lệ như retry hoặc queue trước khi sửa.'],'Latency giảm theo cohort liên quan, outcome không regression và có bằng chứng root cause.'],
    ['Một dashboard đẹp không chứng minh đã instrument đúng hoặc đang nhận dữ liệu live.','Đừng log toàn prompt/tool output theo mặc định nếu chứa dữ liệu nhạy cảm.'],
    [['Vì sao cần trace ID?','Để nối log/span và feedback thuộc cùng request qua nhiều thành phần.'],['Metrics có thay logs không?','Không. Tổng hợp cho xu hướng nhưng thường thiếu chi tiết sự kiện cần điều tra.'],['Tỷ lệ 200 cao nhưng quality giảm thì sao?','Thêm metric/outcome eval và phân cohort; nhiều lỗi AI là sai nội dung/hành động mà HTTP vẫn thành công.']]);

  O(14,
    'Evaluation biến nhận xét “model tốt hơn” thành phép so có dữ liệu, tiêu chí và giới hạn. Benchmark chỉ có ý nghĩa trong task, tập mẫu và điều kiện chạy đã định.',
    'Thiết kế golden dataset, chọn metric/judge phù hợp, phân tích failure clusters và quyết định gate có cơ sở.',
    [['Định nghĩa thành công','Tách correctness, usefulness, safety, latency và cost theo task.','Rubric có điều kiện'],['Tạo bộ eval','Lấy mẫu đại diện cùng hard cases; có nhãn, nguồn và split tránh leakage.','Golden dataset'],['Chạy baseline và biến thể','Giữ cấu hình/điều kiện so rõ; lưu input, output, context và per-case scores.','Artifact tái hiện được'],['Kiểm evaluator và phân tích','Calibrate judge, xem sai số thống kê và cluster lỗi thay vì chỉ điểm tổng.','Kết luận có giới hạn'],['Đặt gate và regression','Dùng mức lỗi/risk phù hợp để phát hành; lỗi mới trở thành case kiểm lại.','Vòng cải tiến có phép đo']],
    [['Dataset design','Mẫu quyết định phạm vi kết luận','Golden dataset (bộ dữ liệu đánh giá chuẩn) cần đại diện traffic/risk, nhãn được review và holdout; tập quá dễ cho điểm cao nhưng không phản ánh lỗi thực.'],['Metrics','Metric phải khớp loại đầu ra','Classification, retrieval, generation và agent actions cần phép đo khác nhau; accuracy, recall, grounding hay task success không thay thế lẫn nhau.'],['LLM-as-judge','Judge cần được đánh giá','LLM-as-judge (dùng model làm bộ chấm) có bias vị trí, độ dài và phong cách; cần rubric, nhãn người và kiểm agreement theo failure mode.'],['Statistical rigor','Điểm tăng có thể do nhiễu','Xét cỡ mẫu, variance và điều kiện chạy; dùng cặp case tương đương và khoảng bất định phù hợp, không kết luận mạnh từ vài mẫu.'],['Failure analysis','Tìm cụm lỗi để sửa đúng','Failure analysis (phân tích lỗi) gom case theo nguyên nhân như retrieval, reasoning, tool hoặc policy; xem per-case evidence trước quyết định giải pháp.']],
    ['Tách RAG component metrics khỏi E2E task evaluation.','Đánh giá trajectory và quyền bên cạnh outcome; safety cases cần cả allowed/disallowed requests.'],
    ['Thiết kế thống kê và benchmark phức tạp khi đã có dataset, rubric và artifact đáng tin.'],
    ['Model B hơn A hai điểm trên 20 câu và đội muốn phát hành ngay.',['Kiểm bộ câu có đại diện, trùng train hay không và các điều kiện chạy.','Xem per-case wins/losses, độ biến thiên và lỗi nghiêm trọng.','Mở rộng mẫu có mục đích để giải quyết bất định còn lại trước gate.'],'Kết luận nêu phạm vi và uncertainty; không đánh đổi lỗi nghiêm trọng bằng điểm trung bình.'],
    ['Không lấy target trong báo cáo mẫu làm actual đã đạt.','Tối ưu trên bộ eval lặp đi lặp lại có thể làm mất tính độc lập của phép đo.'],
    [['Eval set khác train set để làm gì?','Để kiểm khả năng tổng quát và tránh coi việc học thuộc dữ liệu đã tối ưu là chất lượng ngoài mẫu.'],['Điểm tổng tăng nhưng có cần từ chối release không?','Có thể, nếu xuất hiện regression nghiêm trọng, vi phạm ràng buộc hoặc tăng cost/latency vượt gate.'],['Failure cluster giúp gì?','Chỉ ra nhóm nguyên nhân và lớp cần sửa, rồi tạo regression cases xác nhận bản sửa có tác dụng.']]);

  O(15,
    'Sẵn sàng triển khai thực tế là đáp ứng đồng thời giá trị, dữ liệu, bảo mật, vận hành và chi phí. Tối ưu phải giữ chất lượng cốt lõi và khả năng phục hồi.',
    'Lập một readiness review có tổng chi phí, đường scale, rollback và roadmap theo rủi ro thực.',
    [['Chốt phạm vi phục vụ','Xác định user, traffic, loại dữ liệu, outcome và mức risk cho phép.','Service envelope'],['Kiểm readiness','Kiểm identity, quyền, dữ liệu, eval, owner và vận hành theo phạm vi.','Khoảng trống ưu tiên'],['Dự toán tổng chi phí','Tính model, hạ tầng, dữ liệu, nhân lực review/vận hành và lỗi.','Cost model có giả định'],['Tối ưu và thử tải','Chọn cache, routing, batch hoặc model nhỏ theo bottleneck; đo lại quality và reliability.','Cấu hình có đánh đổi rõ'],['Rollout và roadmap','Triển khai từng phần, theo dõi outcome, rollback được và ưu tiên kỹ năng/kiến trúc tiếp.','Kế hoạch cải tiến']],
    [['Enterprise readiness','Readiness là nhiều lớp bằng chứng','Enterprise readiness (mức sẵn sàng cho tổ chức) cần governance, security, integration, quality, support và owner; không có một checklist ngưỡng cố định cho mọi domain.'],['Cost anatomy','Tổng chi phí vượt hóa đơn API','TCO — total cost of ownership (tổng chi phí sở hữu) gồm build, model, data, hạ tầng, người review, vận hành và chi phí lỗi.'],['Optimization','Tối ưu một chiều có thể hỏng chiều khác','Cache, routing, batch, context trimming và model nhỏ có thể giảm chi phí nhưng cần kiểm freshness, task success và latency theo cohort.'],['Scaling & reliability','Scale theo bottleneck thật','Tải có thể kẹt ở DB, queue, network, provider quota hoặc state; tăng replica app không tự giải mọi tầng.'],['Skills & roadmap','Ưu tiên theo lỗi và mục tiêu','Roadmap (lộ trình cải tiến) nên nối evidence về khoảng trống tới việc cần học/xây; ưu tiên hiểu–build–evaluate–debug–deploy trước mở rộng phức tạp.']],
    ['Có runbook, owner on-call, feedback và incident-to-regression loop theo mức dịch vụ cần giữ.','Báo rõ khác biệt giữa mock, integration live, deployment và business outcome đã verify.'],
    ['Tối ưu đa vùng, GPU serving hoặc model tùy chỉnh khi có số liệu chứng minh nhu cầu.'],
    ['Demo chạy tốt nhưng người review phải sửa gần mọi câu, làm dự án đắt hơn cách cũ.',['Đo task success sau review và effort thực tế thay vì chỉ token bill.','Tìm nhóm task có giá trị cao, giới hạn scope và cải thiện lỗi chủ đạo.','So lại ROI/TCO với baseline trước mở rộng traffic.'],'Giá trị ròng và mức lỗi đạt yêu cầu với dữ liệu/giả định được công khai.'],
    ['Không coi hoàn tất học phần là bằng chứng hệ thống production-ready.','Đừng tối ưu cost trước khi biết chất lượng tối thiểu phải giữ và bottleneck thực.'],
    [['TCO gồm những khoản nào?','Chi phí xây dựng, API/model, hạ tầng, dữ liệu, review/vận hành, tích hợp và hậu quả lỗi theo phạm vi.'],['Tối ưu xong cần đo lại gì?','Quality, safety, freshness/quyền, latency, reliability và cost trên cùng workload đại diện.'],['Roadmap tốt bắt đầu từ đâu?','Từ outcome/risk và khoảng trống có evidence, với owner và phép kiểm hoàn tất cho từng cải tiến.']]);

  window.LESSON_OVERVIEWS=all;
})();
